  facilities?: Array<string>;
  // Unique accommodation ID
  id?: number;
  // Location information for the property
  location?: {
  // Property address
  address: string;
  // City name
  city_name?: string;
  // Geographic coordinates of the property
  coordinates?: {
  // Property latitude coordinate
  latitude: number;
  // Property longitude coordinate
  longitude: number;
};
  // Country code (ISO 3166-1 alpha-2)
  country_code: string;
  // Country name
  country_name?: string;
  // District name
  district_name?: string;
  // Postal code
  postal_code?: string;
};
  // The official name of the accommodation as listed by the property owner. This could be a hotel name, apartment title, or vacation rental property name.
  name: string;
  // Complete pricing information for this accommodation including the total cost and currency. Additional taxes, fees, or charges may apply and will be shown during the booking process.
  price?: {
  // The display price that must be shown to the traveller under local booker protection laws. This price includes the base accommodation cost and all charges that are legally required to be part of the displayed price. Equivalent to base + included charges.
  book: number;
