/** Filter for the home activity feed. Default “all” mixes notifications + runs. */
export type ActivityFilter =
	| "all"
	| "notifications"
	| "behavior_runs"
	| "syncs"
	| "clients";

const FILTER_OPTIONS: { value: ActivityFilter; label: string }[] = [
	{ value: "all", label: "All activity" },
	{ value: "notifications", label: "Notifications" },
	{ value: "behavior_runs", label: "Behavior runs" },
	{ value: "syncs", label: "Feed syncs" },
	{ value: "clients", label: "Client apps" },
];

/**
 * Home activity filter with a notifications-first default: start on
 * "notifications", and once that feed loads empty, fall back to "all" — but
 * only if the user hasn't already picked a filter. Any manual change sticks.
 * Returns [filter, setFilter] like useState; wrap onFilterChange with the
 * returned setter so manual selections suppress the auto-fallback.
 */
export function useNotificationsFirstFilter(): [
	ActivityFilter,
	(next: ActivityFilter) => void,
] {
	const { session } = useAuthState();
	const { orgContext } = useOrgContext();
	const [filter, setFilter] = useState<ActivityFilter>("notifications");
	const userPicked = useRef(false);

	const { data, isSuccess } = useNotifications(session ? orgContext : null);
	const isEmpty =
		isSuccess &&
		(data?.pages.flatMap((p) => p.notifications).length ?? 0) === 0;

	useEffect(() => {
		// Auto-fallback to "all" only on the initial empty-notifications load,
		// and never after the user has made an explicit choice.
		if (isEmpty && !userPicked.current && filter === "notifications") {
			setFilter("all");
		}
	}, [isEmpty, filter]);

	const setFilterFromUser = (next: ActivityFilter) => {
		userPicked.current = true;
		setFilter(next);
	};

	return [filter, setFilterFromUser];
}

type TimelineKind =
	| "notification"
	| "behavior_run"
	| "behavior_run_group"
	| "sync"
	| "sync_group"
	| "run"
	| "run_group";

interface TimelineItem {
	id: string;
	kind: TimelineKind;
	at: number;
	title: string;
	body?: string | null;
	unread?: boolean;
	status?: string;
	href?: string | null;
	/** The specific run this item represents (for peek pane deep-link). */
	runId?: number | null;
	notification?: NotificationItem;
	/** Approval run id when this is an action_approval_needed card. */
	approvalRunId?: number | null;
	/** Kind of pending interaction behind the card ('approval' today). */
	interactionType?: string | null;
	/** Live interaction state from its authoritative per-type source. */
	interactionStatus?: string | null;
	/** Server policy: this interaction can be completed inline from the feed. */
	interactionInline?: boolean;
	notificationId?: number | null;
}

/** Navigate preserving query strings (TanStack `to: full?query` drops `?…`). */
function useOpenAppHref() {
	const navigate = useNavigate();
	return (href: string) => {
		const { pathname, search } = parseAppHref(href);
		void navigate({
			to: pathname as "/",
			search: (search ?? {}) as never,
		});
	};
}

/** Link that accepts a full app-relative href including query. */
function AppHrefLink({
	href,
	className,
	onClick,
	children,
}: {
	href: string;
	className?: string;
	onClick?: (e: React.MouseEvent) => void;
	children: ReactNode;
}) {
	const { pathname, search } = parseAppHref(href);
	return (
		<Link
			to={pathname as "/"}
			search={(search ?? {}) as never}
			className={className}
			onClick={onClick}
		>
			{children}
		</Link>
	);
}

function notificationIcon(type: string, isRead: boolean) {
	if (!isRead) {
		return <span className="mt-1 h-2 w-2 shrink-0 rounded-full bg-blue-500" />;
	}
	const iconClass = "mt-0.5 h-4 w-4 shrink-0 text-muted-foreground";
	switch (type) {
		case "action_approval_needed":
			return <GitPullRequest className={iconClass} />;
		case "connection_permission_request":
		case "browser_auth_expired":
			return <Link2 className={iconClass} />;
		case "invitation_received":
			return <Mail className={iconClass} />;
		case "agent_message":
			return <Bot className={iconClass} />;
		default:
			return <Bell className={iconClass} />;
	}
}

function RunStatusIcon({ status }: { status: string }) {
	if (status === "completed")
		return <CheckCircle2 className="h-4 w-4 shrink-0 text-green-500" />;
	if (isFailedRunStatus(status))
		return <XCircle className="h-4 w-4 shrink-0 text-destructive" />;
	if (status === "running" || status === "claimed")
		return <Spinner size="md" className="shrink-0 text-blue-500" />;
	return <Clock className="h-4 w-4 shrink-0 text-muted-foreground" />;
}

function kindLabel(kind: TimelineKind, notificationType?: string): string {
	if (kind === "notification" && notificationType) {
		return notificationKindLabel(notificationType);
	}
	if (kind === "notification") return "Notification";
	switch (kind) {
		case "behavior_run":
		case "behavior_run_group":
			return "Behavior run";
		case "sync":
		case "sync_group":
			return "Feed sync";
		default:
			return "Run";
	}
}

function mapServerKind(kind: string): TimelineKind {
	if (kind === "notification") return "notification";
	if (kind === "behavior_run" || kind === "behavior_run_group")
		return kind as TimelineKind;
	if (kind === "sync" || kind === "sync_group") return kind as TimelineKind;
	if (kind === "run_group") return "run_group";
	return "run";
}

/** Sticky header controls for the home activity feed. */
export function HomeActivityToolbar({
	filter,
	onFilterChange,
}: {
	filter: ActivityFilter;
	onFilterChange: (value: ActivityFilter) => void;
}) {
	const { session } = useAuthState();
	const { orgContext } = useOrgContext();
	const wantNotifs = filter === "all" || filter === "notifications";
	const { data: notifData } = useNotifications(
		session && wantNotifs ? orgContext : null,
	);
	const markAllRead = useMarkAllNotificationsRead(orgContext);
	const notifications = useMemo(
		() => notifData?.pages.flatMap((p) => p.notifications) ?? [],
		[notifData],
	);
	const hasUnread = notifications.some((n) => !n.is_read);

	return (
		<div className="flex flex-wrap items-center justify-center gap-x-3 gap-y-1">
			<div className="flex min-w-0 items-center gap-2">
				<p className="text-xs font-medium uppercase tracking-wide text-muted-foreground">
					Activity
				</p>
				<Select
					value={filter}
					onValueChange={(v) => onFilterChange(v as ActivityFilter)}
				>
					<SelectTrigger
						className="h-7 w-[9.5rem] border-0 bg-muted/40 text-xs shadow-none"
						aria-label="Filter activity"
					>
						<SelectValue />
					</SelectTrigger>
					<SelectContent>
						{FILTER_OPTIONS.map((opt) => (
							<SelectItem key={opt.value} value={opt.value}>
								{opt.label}
							</SelectItem>
						))}
					</SelectContent>
				</Select>
			</div>
			{wantNotifs && hasUnread ? (
				<button
					type="button"
					onClick={() => void markAllRead.mutateAsync()}
					disabled={markAllRead.isPending}
					className="inline-flex items-center gap-1 text-xs text-muted-foreground transition-colors hover:text-foreground"
				>
					<CheckCheck className="h-3.5 w-3.5" />
					Mark all read
				</button>
			) : null}
		</div>
	);
}

function ApprovalActions({
	runId,
	notificationId,
	reviewHref,
	reviewTitle,
	onSettled,
}: {
	runId: number;
	notificationId: number;
	/** Deep-link to Memory ActionApprovalCard (schema form). */
	reviewHref?: string | null;
	/** Pane header title when the CTA opens the peek pane. */
	reviewTitle?: string;
	onSettled?: () => void;
}) {
	const { orgContext } = useOrgContext();
	const approveRun = useApproveRun();
	const rejectRun = useRejectRun();
	const markRead = useMarkNotificationRead(orgContext);
	const queryClient = useQueryClient();
	const peek = useNotificationPeek();
	const [resolved, setResolved] = useState<"approved" | "rejected" | null>(
		null,
	);
	const [showReject, setShowReject] = useState(false);
	const [reason, setReason] = useState("");
	const busy = approveRun.isPending || rejectRun.isPending;

	const invalidate = () => {
		void queryClient.invalidateQueries({ queryKey: ["activity-feed"] });
		void queryClient.invalidateQueries({ queryKey: ["recent-runs"] });
		void queryClient.invalidateQueries({ queryKey: ["notifications"] });
		void queryClient.invalidateQueries({
			queryKey: ["notifications-unread-count"],
		});
		onSettled?.();
	};

	if (resolved === "approved") {
		return (
			<p className="mt-2 text-xs font-medium text-emerald-600 dark:text-emerald-400">
				Approved — executing…
			</p>
		);
	}
	if (resolved === "rejected") {
		return (
			<p className="mt-2 text-xs font-medium text-muted-foreground">Rejected</p>
		);
	}

	if (showReject) {
		return (
			<div className="mt-2 flex flex-wrap items-center gap-2">
				<input
					type="text"
					placeholder="Reason (optional)"
					value={reason}
					onChange={(e) => setReason(e.target.value)}
					className="h-7 min-w-[10rem] flex-1 rounded-md border bg-background px-2 text-xs"
					onClick={(e) => e.stopPropagation()}
				/>
				<Button
					size="sm"
					variant="outline"
					className="h-7 text-xs"
					disabled={busy}
					onClick={(e) => {
						e.stopPropagation();
						rejectRun.mutate(
							{ run_id: runId, reason: reason.trim() || undefined },
							{
								onSuccess: () => {
									setResolved("rejected");
									markRead.mutate(notificationId);
									invalidate();
								},
							},
						);
					}}
				>
					{rejectRun.isPending ? (
						<Spinner size="sm" className="mr-1" />
					) : (
						<X className="mr-1 h-3 w-3" />
					)}
					Reject
				</Button>
				<button
					type="button"
					className="text-xs text-muted-foreground hover:text-foreground"
					onClick={(e) => {
						e.stopPropagation();
						setShowReject(false);
					}}
				>
					Cancel
				</button>
			</div>
		);
	}

	return (
		<div className="mt-2 flex flex-wrap items-center gap-2">
			{reviewHref ? (
				// Peek is the default destination — the detail is a preview, not a
				// context switch. The pane carries an "Open full page" link for the
				// cases that want the real route. Falls back to navigation when the
				// href isn't previewable or no provider is mounted.
				peek && parsePeekHref(reviewHref) ? (
					<Button
						type="button"
						size="sm"
						variant="outline"
						className="h-7 text-xs"
						onClick={(e) => {
							e.stopPropagation();
							markRead.mutate(notificationId);
							peek.open({
								href: reviewHref,
								title: reviewTitle ?? "Approval",
								runId,
							});
						}}
					>
						Review
					</Button>
				) : (
					<AppHrefLink
						href={reviewHref}
						className={cn(
							"inline-flex h-7 items-center justify-center rounded-md border border-input bg-background px-3 text-xs font-medium shadow-xs transition-colors hover:bg-accent hover:text-accent-foreground",
						)}
						onClick={(e) => {
							e.stopPropagation();
							markRead.mutate(notificationId);
						}}
					>
						Review
					</AppHrefLink>
				)
			) : null}
			<Button
				size="sm"
				className="h-7 text-xs"
				disabled={busy}
				onClick={(e) => {
					e.stopPropagation();
					approveRun.mutate(
						{ run_id: runId },
						{
							onSuccess: () => {
								setResolved("approved");
								markRead.mutate(notificationId);
								invalidate();
							},
						},
					);
				}}
			>
				{approveRun.isPending ? (
					<Spinner size="sm" className="mr-1" />
				) : (
					<Check className="mr-1 h-3 w-3" />
				)}
				Approve
			</Button>
			<Button
				size="sm"
				variant="outline"
				className="h-7 text-xs"
				disabled={busy}
				onClick={(e) => {
					e.stopPropagation();
					setShowReject(true);
				}}
			>
				<X className="mr-1 h-3 w-3" />
				Reject
			</Button>
		</div>
	);
}

/**
 * Home empty-chat activity list (filter controlled by sticky header toolbar).
 */
export function HomeAttentionTimeline({
	owner,
	filter,
	agentId,
}: {
	owner: string;
	filter: ActivityFilter;
	/**
	 * When set, scope the feed to this agent's runs. The server drops
	 * notifications for an agent-scoped feed, so only run cards appear.
	 */
	agentId?: string;
}) {
	const openHref = useOpenAppHref();
	const peek = useNotificationPeek();
	const { session } = useAuthState();
	const { orgContext } = useOrgContext();
	const markRead = useMarkNotificationRead(orgContext);

	// MCP client sessions come from their own org-level endpoint, not
	// list_activity — the dedicated filter renders that list instead. Kept as
	// an early return so the notification/run mapping below stays untouched.
	const isClientsFilter = filter === "clients" && !agentId;

	const kinds = useMemo((): string[] | undefined => {
		if (filter === "notifications") return ["notification"];
		if (filter === "behavior_runs") return ["behavior"];
		if (filter === "syncs") return ["sync"];
		return undefined;
	}, [filter]);

	// An agent-scoped feed never carries notifications; don't request them.
	const wantNotifications =
		!agentId && filter !== "behavior_runs" && filter !== "syncs";

	const {
		data: cards = [],
		isLoading,
		isError,
	} = useActivityFeed(session && !isClientsFilter ? owner : null, {
		limit: 24,
		aggregate: true,
		includeNotifications: wantNotifications,
		includeRuns: filter !== "notifications",
		kinds,
		agentId,
	});

	// Server returns attention order (oldest→newest after collapse). Keep as-is
	// for the bottom-anchored chat empty state.
	const items = useMemo((): TimelineItem[] => {
		return cards.map((c) => {
			const kind = mapServerKind(c.kind);
			const isApproval =
				kind === "notification" && c.status === "action_approval_needed";
			return {
				id: c.id,
				kind,
				at: new Date(c.at).getTime(),
				title: c.title,
				body: c.body,
				unread: c.unread,
				status: c.status ?? undefined,
				href: c.href,
				runId: c.run_id ?? null,
				approvalRunId: isApproval ? (c.run_id ?? null) : null,
				interactionType: isApproval ? (c.interaction_type ?? null) : null,
				interactionStatus: isApproval ? (c.interaction_status ?? null) : null,
				interactionInline: isApproval ? (c.interaction_inline ?? false) : false,
				notificationId: c.notification_id ?? null,
				// Synthetic NotificationItem for approval actions / mark-read
				notification:
					kind === "notification" && c.notification_id != null
						? ({
								id: c.notification_id,
								type: c.status ?? "generic",
								title: c.title,
								body: c.body,
								resource_url: c.href,
								resource_type: c.run_id != null ? "run" : null,
								resource_id: c.run_id != null ? String(c.run_id) : null,
								is_read: !c.unread,
								created_at: c.at,
								organization_id: "",
								user_id: "",
							} satisfies NotificationItem)
						: undefined,
			};
		});
	}, [cards]);

	const openItem = (item: TimelineItem) => {
		if (!item.href) return;
		if (
			item.kind === "notification" &&
			item.notificationId != null &&
			item.unread
		) {
			markRead.mutate(item.notificationId);
		}
		// Prefer the right-side peek pane when the item is previewable and a
		// provider is present (workspace surfaces). open() sticks the target
		// into the URL (`?peek=1&peek_run_id=…`) so reloads / deep-links match a
		// click. Falls back to a normal navigate() elsewhere. The explicit CTA
		// button still opens the full page.
		if (peek && parsePeekHref(item.href)) {
			peek.open({
				href: item.href,
				title: item.title,
				runId: item.runId ?? undefined,
			});
			return;
		}
		openHref(item.href);
	};

	if (!session) {
		return (
			<p className="py-6 text-center text-sm text-muted-foreground">
				Sign in to see workspace activity.
			</p>
		);
	}

	if (isClientsFilter) {
		return <ClientSessionsTimeline owner={owner} />;
	}

	if (isLoading && items.length === 0) {
		return (
			<div className="space-y-2">
				{Array.from({ length: 4 }).map((_, i) => (
					<div
						// biome-ignore lint/suspicious/noArrayIndexKey: static skeleton
						key={i}
						className={cn(FILLED_BOX, "h-14 animate-pulse")}
					/>
				))}
			</div>
		);
	}

	if (isError) {
		return (
			<p className="py-6 text-center text-sm text-destructive">
				Could not load recent activity.
			</p>
		);
	}

	if (items.length === 0) {
		const emptyCopy =
			filter === "notifications"
				? "No notifications yet."
				: filter === "behavior_runs"
					? "No Behavior runs yet."
					: filter === "syncs"
						? "No feed syncs yet."
						: "No recent activity yet.";
		return (
			<div className="flex flex-col items-center gap-2 py-8 text-center">
				<Bell className="h-8 w-8 text-muted-foreground/50" />
				<p className="text-sm text-muted-foreground">{emptyCopy}</p>
			</div>
		);
	}

	return (
		<ul className="space-y-1">
			{items.map((item) => {
				const approvalRunId = item.approvalRunId ?? null;
				// Gate action UI on the card's interaction kind — the generic
				// contract — not the notification type. A future interaction kind
				// adds its own branch here without changing the card shape.
				const isApprovalInteraction = item.interactionType === "approval";
				// interaction_status is NOT a fixed enum (contract: treat any value
				// not explicitly handled as non-actionable). Every resolved
				// non-pending status renders as a neutral outcome chip — an unknown
				// value like 'auto' must never fall through to an actionable CTA.
				const approvalOutcome = isApprovalInteraction
					? item.interactionStatus === "approved"
						? "Approved"
						: item.interactionStatus === "rejected"
							? "Rejected"
							: item.interactionStatus === "expired"
								? "Expired"
								: item.interactionStatus &&
										item.interactionStatus !== "pending"
									? item.interactionStatus.charAt(0).toUpperCase() +
										item.interactionStatus.slice(1)
									: null
					: null;
				const showInlineApproval =
					isApprovalInteraction &&
					item.interactionStatus === "pending" &&
					item.interactionInline === true &&
					approvalRunId != null;
				const actionLabel =
					!showInlineApproval && !approvalOutcome && item.notification
						? notificationActionLabel(item.notification.type, item.href)
						: null;
				const itemKindLabel =
					isApprovalInteraction && approvalOutcome
						? "Approval"
						: kindLabel(item.kind, item.notification?.type);

				const clickable = Boolean(item.href);
				// Notification rows use the compact Markdown preview. Run and sync
				// bodies are status/error text and retain their existing raw display.
				const summaryText =
					item.kind === "notification"
						? notificationSummaryMarkdown(item.body)
						: null;
				const rowClass = cn(
					FILLED_BOX,
					"flex w-full items-start gap-3 p-3 text-left transition-colors",
					clickable && "hover:bg-accent/50",
				);
				const icon =
					item.kind === "notification" && item.notification ? (
						notificationIcon(item.notification.type, !item.unread)
					) : item.kind === "sync" || item.kind === "sync_group" ? (
						item.status ? (
							<RunStatusIcon status={item.status} />
						) : (
							<RefreshCw className="mt-0.5 h-4 w-4 shrink-0 text-muted-foreground" />
						)
					) : item.kind === "behavior_run" ||
						item.kind === "behavior_run_group" ||
						item.kind === "run" ||
						item.kind === "run_group" ? (
						item.status ? (
							<RunStatusIcon status={item.status} />
						) : (
							<Eye className="mt-0.5 h-4 w-4 shrink-0 text-muted-foreground" />
						)
					) : (
						<Bell className="mt-0.5 h-4 w-4 shrink-0 text-muted-foreground" />
					);

				const body = (
					<>
						{icon}
						<div className="min-w-0 flex-1">
							<div className="flex items-baseline gap-2">
								<p
									className={cn(
										"min-w-0 flex-1 truncate text-sm",
										item.unread
											? "font-medium text-foreground"
											: "text-foreground/90",
									)}
								>
									{item.title}
								</p>
								<span className="shrink-0 text-[11px] text-muted-foreground">
									{formatTimeAgo(item.at)}
								</span>
							</div>
							{summaryText ? (
								// Summary only — the detail list and review link live in the
								// focused/peek view. Links inside stop propagation so they
								// don't also trigger the row's open-peek handler.
								// biome-ignore lint/a11y/noStaticElementInteractions: wrapper only stops bubbling from nested links
								// biome-ignore lint/a11y/useKeyWithClickEvents: no own behaviour; the row handles keyboard
								<div
									className="mt-0.5 line-clamp-2 text-xs text-muted-foreground"
									onClick={(e) => {
										if ((e.target as HTMLElement).closest("a")) {
											e.stopPropagation();
										}
									}}
								>
									<InlineMarkdownText
										text={summaryText}
										// Approval bodies are server-composed and carry our own
										// entity permalinks, so same-origin anchors survive; the
										// renderer drops external ones either way. Every other type
										// — above all agent_message, whose body an agent supplies
										// verbatim — renders link text with no anchor at all.
										linkPolicy={
											item.notification?.type === "action_approval_needed"
												? "app-links"
												: "strip"
