import { createFileRoute } from "@tanstack/react-router";
import { pickPeekSearch } from "@/lib/peek-search";

// Home chat is rendered by the owner layout (`HomeBuilderSurface`). This leaf
// matches `/` and optional `?new` / `?prompt` (fresh draft / prefilled composer).
// Peek keys must pass through so activity-timeline clicks that land on home
// (or redirect via home) keep the right-side peek open.
export const Route = createFileRoute("/$owner/")({
	validateSearch: (
		search: Record<string, unknown>,
	): Record<string, string | true | undefined> => {
		const out: Record<string, string | true | undefined> = {};
		if (search.new === true || search.new === "1" || search.new === "true") {
			out.new = true;
		}
		if (typeof search.prompt === "string" && search.prompt.length > 0) {
			out.prompt = search.prompt;
		}
		Object.assign(out, pickPeekSearch(search));
		return out;
	},
	component: () => null,
});
import { useQuery } from "@tanstack/react-query";
import { apiCall } from "./core";

export type ActivityCard = {
	id: string;
	kind: string;
	title: string;
	body: string | null;
	at: string;
	status: string | null;
	count: number;
	href: string | null;
	unread?: boolean;
	notification_id?: number;
	run_id?: number;
	/**
	 * Kind of pending interaction behind this notification (events
	 * `interaction_type` vocabulary — 'approval' today). Clients pick the UI
	 * for the type; new interaction kinds extend the value, not the card shape.
	 */
	interaction_type?: string;
	/**
	 * Live interaction state from its authoritative per-type source. For
	 * 'approval': 'pending' | 'approved' | 'rejected' (the run's state machine).
	 */
	interaction_status?: string;
	/** Server policy: this interaction can be completed inline from the feed. */
	interaction_inline?: boolean;
	member_run_ids?: number[];
	connection_id?: number;
	behavior_id?: number;
};

type ListActivityResult = {
	action: "list_activity";
	items: ActivityCard[];
	total: number;
	limit: number;
};

export type ActivityFeedOpts = {
	limit?: number;
	includeNotifications?: boolean;
	includeRuns?: boolean;
	aggregate?: boolean;
	kinds?: string[];
	/** Scope the feed to a single agent's runs (drops notifications server-side). */
	agentId?: string;
};

/**
 * Workspace attention feed (manage_operations.list_activity) — aggregated
 * notifications + user-facing runs with deep-links.
 */
export function useActivityFeed(
	ownerSlug: string | null,
	opts?: ActivityFeedOpts,
) {
	const limit = opts?.limit ?? 24;
	const aggregate = opts?.aggregate !== false;
	const includeNotifications = opts?.includeNotifications !== false;
	const includeRuns = opts?.includeRuns !== false;
	const kinds = opts?.kinds;
	const agentId = opts?.agentId;

	return useQuery({
		queryKey: [
			"activity-feed",
			ownerSlug ?? null,
			limit,
			aggregate,
			includeNotifications,
			includeRuns,
			kinds?.join(",") ?? null,
			agentId ?? null,
		],
		queryFn: async () => {
			const res = await apiCall<ListActivityResult>(
				"manage_operations",
				{
					action: "list_activity",
					limit,
					aggregate,
					include_notifications: includeNotifications,
					include_runs: includeRuns,
					...(kinds?.length ? { kinds } : {}),
					...(agentId ? { agent_id: agentId } : {}),
				},
				ownerSlug ? { slug: ownerSlug } : undefined,
			);
			return res.items ?? [];
		},
		enabled: !!ownerSlug,
		staleTime: 15_000,
		refetchInterval: 30_000,
	});
}
import { Hono } from "hono";
import { mcpAuth } from "../auth/middleware";
import { getDb } from "../db/client";
import type { Env } from "../index";

/** Recent org-wide MCP session activity derived from tool-invocation audits. */
const routes = new Hono<{ Bindings: Env }>();

const ACTIVITY_WINDOW_DAYS = 14;

interface SessionRow {
	session_id: string;
	client_id: string | null;
	client_name: string | null;
	user_id: string | null;
	agent_id: string | null;
	first_call_at: Date;
	last_call_at: Date;
	call_count: string;
	failed_count: string;
	tools: string[] | null;
	pending_interaction_count: string;
}

routes.get("/", mcpAuth, async (c) => {
	const organizationId = c.get("organizationId") as string | undefined;
	if (!organizationId) {
		return c.json({ error: "Organization required" }, 401);
	}
	const rawLimit = Number.parseInt(c.req.query("limit") ?? "20", 10);
	const limit = Math.min(Math.max(Number.isNaN(rawLimit) ? 20 : rawLimit, 1), 100);

	const sql = getDb();
	const rows = (await sql`
		WITH session_calls AS (
			SELECT
				e.metadata->>'mcp_session_id' AS session_id,
				e.client_id,
				e.created_by,
				e.metadata->>'agent_id' AS agent_id,
				e.payload_data->>'tool_name' AS tool_name,
				(e.payload_data->>'success')::boolean AS success,
				e.occurred_at
			FROM events e
			WHERE e.organization_id = ${organizationId}
				AND e.semantic_type = 'audit'
				AND e.origin_type = 'tool_invocation'
				AND e.metadata->>'mcp_session_id' IS NOT NULL
				AND e.occurred_at > now() - make_interval(days => ${ACTIVITY_WINDOW_DAYS})
		),
		sessions AS (
			SELECT
				session_id,
				max(client_id) AS client_id,
				max(created_by) AS user_id,
				max(agent_id) AS agent_id,
				min(occurred_at) AS first_call_at,
				max(occurred_at) AS last_call_at,
				count(*) AS call_count,
				count(*) FILTER (WHERE success IS NOT TRUE) AS failed_count,
				-- to_jsonb: raw text[] arrives as an unparsed "{a,b}" string under
				-- the prod fetch_types:false client options; jsonb parses cleanly.
				to_jsonb((array_agg(DISTINCT tool_name ORDER BY tool_name))[1:8]) AS tools
			FROM session_calls
			GROUP BY session_id
		),
		pending_interactions AS (
			SELECT
				a.metadata->>'mcp_session_id' AS session_id,
				count(*) AS pending_interaction_count
			FROM current_event_records a
			WHERE a.organization_id = ${organizationId}
				AND a.interaction_type <> 'none'
				AND a.interaction_status = 'pending'
				AND a.metadata->>'mcp_session_id' IS NOT NULL
			GROUP BY a.metadata->>'mcp_session_id'
		)
		SELECT
			s.*,
			oc.client_name,
			coalesce(pi.pending_interaction_count, 0) AS pending_interaction_count
		FROM sessions s
		LEFT JOIN oauth_clients oc ON oc.id = s.client_id
		LEFT JOIN pending_interactions pi ON pi.session_id = s.session_id
		ORDER BY last_call_at DESC
		LIMIT ${limit}
	`) as unknown as SessionRow[];

	return c.json({
		sessions: rows.map((row) => ({
			sessionId: row.session_id,
			clientId: row.client_id,
			clientName: row.client_name,
			userId: row.user_id,
			agentId: row.agent_id,
			firstCallAt: new Date(row.first_call_at).getTime(),
			lastCallAt: new Date(row.last_call_at).getTime(),
			callCount: Number(row.call_count),
			failedCount: Number(row.failed_count),
			tools: row.tools ?? [],
			pendingInteractionCount: Number(row.pending_interaction_count),
		})),
	});
});

export const clientSessionRoutes = routes;
