import {
	createFileRoute,
	Navigate,
	Outlet,
	useLocation,
} from "@tanstack/react-router";
import {
	AgentWorkbenchHeaderSkeleton,
	ChatRoutePendingShell,
} from "@/components/agents/agent-loading-shells";
import { NotificationPeekProvider } from "@/components/peek/notification-peek-context";
import { NotificationPeekPane } from "@/components/peek/notification-peek-pane";
import { agentChatLink, isOwnerHomePath } from "@/lib/agent-chat-routes";
import { useAgents, useSystemAgentId, useWorkspaceRoot } from "@/lib/api";
import { systemAgentQueryOptions } from "@/lib/api/agents";
import { isServerError } from "@/lib/api/core";
import { useAuthState } from "@/lib/auth-state";
import { useAnonymousSignInRedirect } from "@/lib/sign-in-redirect";

export const Route = createFileRoute("/$owner")({
	loader: ({ context: { queryClient }, params }) => {
		// Fire-and-forget — awaiting here blocks child routes behind the router's
		// generic pending UI instead of each page's shape-matched skeletons.
		void queryClient.prefetchQuery(
			useWorkspaceRoot.queryOptions(params.owner, { slug: params.owner }),
		);
		void queryClient.prefetchQuery(useAgents.queryOptions(params.owner));
		void queryClient.prefetchQuery(systemAgentQueryOptions(params.owner));
	},
	// Home is builder chat + attention empty state; null avoids a wrong-shaped flash.
	pendingComponent: () => null,
	component: OwnerLayoutRoute,
});

function OwnerLayoutRoute() {
	const { owner } = Route.useParams();
	const { pathname } = useLocation();
	const {
		data: systemAgent,
		isLoading: isSystemAgentLoading,
		error: systemAgentError,
	} = useSystemAgentId();
	const systemAgentId = systemAgent?.systemAgentId ?? null;

	// Auth gate for the whole owner subtree — the chokepoint every
	// `/{owner}/...` page passes through. On a per-org subdomain this is also
	// the landing route: `createSubdomainHistory` rewrites `/` to `/${owner}`
	// before matching, so the `/` route's sign-in redirect never runs there and
	// a signed-out visitor was shown the raw 401 body as a product error.
	// Reuses the workspace query this route's loader already prefetches.
	const {
		data: workspaceRoot,
		isLoading: isWorkspaceLoading,
		error: workspaceError,
	} = useWorkspaceRoot(owner, { slug: owner });
	const { session, isReady: authReady } = useAuthState();
	// A 5xx or transport failure is an outage, not an authz problem; bouncing
	// there would read as "you are not allowed here". Only a refusal — chiefly
	// the 401 a private org answers anonymously — should reach sign-in.
	const isWorkspaceUnavailable =
		isServerError(workspaceError) && !workspaceRoot?.workspace;
	const isRedirectingToSignIn = useAnonymousSignInRedirect({
		active:
			!isWorkspaceLoading &&
			!isWorkspaceUnavailable &&
			authReady &&
			!session &&
			!workspaceRoot?.workspace,
		owner,
	});

	const isHomeView = isOwnerHomePath(owner, pathname);

	// Render nothing while the sign-in navigation lands, so no page in this
	// subtree flashes an auth error on the way to the login screen.
	if (isRedirectingToSignIn) return null;

	if (!isHomeView) {
		return (
			<NotificationPeekProvider>
				<div className="flex min-h-0 flex-1 flex-row">
					{/* `overflow-y-auto`, not `overflow-hidden`: this wrapper is the
					    scroll container for every owner sub-page. The peek pane makes
					    it a flex row, so the shell's outer scroller is clamped to the
					    row height and never sees page overflow — clipping here instead
					    of scrolling made long pages unreachable below the fold. */}
					<div className="flex min-h-0 min-w-0 flex-1 flex-col overflow-y-auto">
						<Outlet />
					</div>
					<NotificationPeekPane />
				</div>
			</NotificationPeekProvider>
		);
	}

	if (isSystemAgentLoading) {
		return (
			<div className="flex min-h-0 flex-1 flex-col gap-3 overflow-hidden py-4 md:py-6">
				<div className="flex shrink-0 flex-col items-center px-4 lg:px-6">
					<AgentWorkbenchHeaderSkeleton />
				</div>
				<div className="flex min-h-0 min-w-0 flex-1 flex-col overflow-hidden px-4 lg:px-6">
					<ChatRoutePendingShell />
				</div>
			</div>
		);
	}

	// Keep load failures distinct from a successful response with no builder.
	if (systemAgentError) {
		return (
			<div className="flex flex-1 flex-col items-center justify-center gap-2 px-4 py-16 text-center">
				<p className="max-w-md text-muted-foreground">
					Couldn't load the workspace builder.
				</p>
				<p className="max-w-md text-sm text-muted-foreground">
					{systemAgentError.message}
				</p>
			</div>
		);
	}

	if (!systemAgentId) {
		return (
			<div className="flex flex-1 flex-col items-center justify-center gap-2 px-4 py-16 text-center">
				<p className="max-w-md text-muted-foreground">
					Workspace builder is not provisioned yet.
				</p>
			</div>
		);
	}
	return (
		<Navigate
			to={agentChatLink(owner, systemAgentId).to}
			params={agentChatLink(owner, systemAgentId).params}
			replace
		/>
	);
}

import { createFileRoute, useParams, useSearch } from "@tanstack/react-router";
import { AgentChatThreadResume } from "@/components/agents/agent-chat-thread-resume";
import {
	HomeActivityToolbar,
	HomeAttentionTimeline,
	useNotificationsFirstFilter,
} from "@/components/home/home-attention-timeline";
import { useSystemAgentId } from "@/lib/api";
import { pickPeekSearch } from "@/lib/peek-search";

export const Route = createFileRoute("/$owner/agents/$agentId/chat")({
	validateSearch: (
		search: Record<string, unknown>,
	): Record<string, string | true | undefined> => {
		const out: Record<string, string | true | undefined> = {};
		if (search.new === true || search.new === "1" || search.new === "true") {
			out.new = true;
		}
		if (typeof search.prompt === "string" && search.prompt.length > 0) {
			out.prompt = search.prompt;
		}
		// Deep-link scroll target from sidepanel handoff (`#message=` → message_id).
		const messageId =
			(typeof search.message_id === "string" && search.message_id.trim()) ||
			(typeof search.message === "string" && search.message.trim()) ||
			"";
		if (messageId) out.message_id = messageId;
		Object.assign(out, pickPeekSearch(search));
		return out;
	},
	component: AgentChatLayout,
});

// Keep the chat panel on the layout route so `/chat` → `/chat/c/$threadId` does
// not remount it (which would drop the just-sent message). The leaf routes render
// nothing; they exist only to match the URL and expose `threadId`.
function AgentChatLayout() {
	const { owner, agentId } = Route.useParams();
	// threadId comes from the deepest match (the `c/$threadId` leaf); `strict:
	// false` reads child params without coupling this layout to that route id.
	const { threadId } = useParams({ strict: false }) as { threadId?: string };
	const { new: newChat, prompt } = useSearch({ strict: false }) as {
		new?: true;
		prompt?: string;
	};

	const { data: systemAgent } = useSystemAgentId();
	const isSystemAgent = systemAgent?.systemAgentId === agentId;
	const [activityFilter, setActivityFilter] = useNotificationsFirstFilter();

	// Landing on the agent (no threadId) must NOT resume the last conversation.
	// Force a fresh composer and fill the empty area with this agent's recent
	// activity — the same timeline Home uses (`home-builder-surface`), reused
	// as-is with `agentId` set so it shows only this agent's Behavior runs
	// (notifications/syncs are org-scoped and dropped server-side). A `?prompt`
	// deep-link still prefills the composer; a named thread (`/chat/c/$threadId`)
	// renders that thread and ignores all of this.
	return (
		<AgentChatThreadResume
			owner={owner}
			agentId={agentId}
			threadId={threadId}
			initialDraft={prompt}
			forceComposer={!threadId}
			newChatRequested={Boolean(newChat)}
			emptyContent={
				<div className="mx-auto w-full max-w-2xl px-1">
					{isSystemAgent && (
						<HomeActivityToolbar
							filter={activityFilter}
							onFilterChange={setActivityFilter}
						/>
					)}
					<HomeAttentionTimeline
						owner={owner}
						filter={isSystemAgent ? activityFilter : "all"}
						agentId={isSystemAgent ? undefined : agentId}
					/>
				</div>
			}
		/>
	);
}
