import { useQuery } from "@tanstack/react-query";
import { useNavigate } from "@tanstack/react-router";
import { type ReactNode, useEffect, useMemo } from "react";
import { AgentChatRoute } from "@/components/agents/agent-chat-route";
import { ChatRoutePendingShell } from "@/components/agents/agent-loading-shells";
import { agentThreadLink } from "@/lib/agent-chat-routes";
import { agentThreadsQueryOptions } from "@/lib/api/agents";

function latestThread<T extends { updatedAt: number }>(
	threads: readonly T[],
): T | undefined {
	return [...threads].sort((a, b) => b.updatedAt - a.updatedAt)[0];
}

/**
 * Resume the newest thread when one exists; otherwise mount a fresh composer.
 * Lives on the chat LAYOUT route so it stays mounted as the URL moves between
 * `/chat` and `/chat/c/$threadId` — see chat.tsx. When `threadId` is set (the
 * URL names a thread) we render that thread directly; otherwise we redirect to
 * the newest thread, or mount a fresh composer when there are none.
 */
export function AgentChatThreadResume({
	owner,
	agentId,
	threadId,
	initialDraft,
	forceComposer = false,
	newChatRequested = false,
	emptyContent,
	preventAutoNavigate,
	buildThreadUrl,
}: {
	owner: string;
	agentId: string;
	/** Set when the URL names a thread (`/chat/c/$threadId`). */
	threadId?: string;
	initialDraft?: string;
	/** `?new` — open a fresh composer even when threads exist (don't resume). */
	forceComposer?: boolean;
	/** `?new` present — rotate the draft so a used composer starts truly fresh. */
	newChatRequested?: boolean;
	emptyContent?: ReactNode;
	/** When true, do not automatically navigate to the materialized thread URL. */
	preventAutoNavigate?: boolean;
	/** Override the URL generated when materializing a draft thread. */
	buildThreadUrl?: (
		owner: string,
		agentId: string,
		threadId: string,
	) => { to: string; params: any };
}) {
	const navigate = useNavigate();
	const { data: threads = [], isLoading } = useQuery(
		agentThreadsQueryOptions(owner, agentId, { strict: false }),
	);
	const latest = useMemo(() => latestThread(threads), [threads]);

	// Only auto-resume the newest thread when the URL does NOT already name one
	// and we're not forcing a fresh composer (`?new`). (Deep-linking to `/chat`
	// should jump to the most recent conversation.) Once the URL carries a
	// threadId we render it directly and never redirect.
	useEffect(() => {
		if (threadId || forceComposer || isLoading || !latest) return;
		const link = buildThreadUrl
			? buildThreadUrl(owner, agentId, latest.id)
			: agentThreadLink(owner, agentId, latest.id);

		void navigate({
			...link,
			replace: true,
		});
	}, [
		agentId,
		isLoading,
		latest,
		navigate,
		owner,
		threadId,
		forceComposer,
		buildThreadUrl,
	]);

	// Always render the same component type (AgentChatRoute) across the
	// composer→thread transition so the panel never remounts and loses the
	// just-sent message. `?new` (forceComposer) shows a fresh composer even when
	// threads exist. Only interpose the pending shell while we're mid-decision
	// (loading, or about to redirect `/chat` → the newest thread).
	if (!threadId && !forceComposer && (isLoading || latest)) {
		return <ChatRoutePendingShell />;
	}

	return (
		<AgentChatRoute
			owner={owner}
			agentId={agentId}
			threadId={threadId}
			initialDraft={initialDraft}
			newChatRequested={newChatRequested}
			emptyContent={emptyContent}
			preventAutoNavigate={preventAutoNavigate}
			buildThreadUrl={buildThreadUrl}
		/>
	);
}
