import { Bot } from "lucide-react";
import type { ReactNode } from "react";
import { AgentChatPanel } from "@/components/agents/agent-chat-panel";
import { AgentChatPanelSkeleton } from "@/components/agents/agent-loading-shells";
import { TabEmptyState } from "@/components/entity-tabs/tab-states";
import { useCurrentOrg } from "@/hooks/use-current-org";
import { useWorkingAgents } from "@/hooks/use-working-agents";
import { useAuthState } from "@/lib/auth-state";

/** Agent workbench chat — single agent. */
export function AgentChatRoute({
	owner,
	agentId,
	threadId,
	initialDraft,
	newChatRequested,
	emptyContent,
	preventAutoNavigate,
	buildThreadUrl,
}: {
	owner: string;
	agentId?: string;
	threadId?: string;
	/** Prefill the composer (from a `?prompt=` deep link). */
	initialDraft?: string;
	/** `?new` — rotate the draft so a used composer starts truly fresh. */
	newChatRequested?: boolean;
	emptyContent?: ReactNode;
	/** When true, do not automatically navigate to the materialized thread URL. */
	preventAutoNavigate?: boolean;
	/** Override the URL generated when materializing a draft thread. */
	buildThreadUrl?: (
		owner: string,
		agentId: string,
		threadId: string,
	) => { to: string; params: any };
}) {
	const { isAuthenticated } = useAuthState();
	const { isMember, isLoading: isOrgLoading } = useCurrentOrg();
	const canManageWorkspace = isAuthenticated && isMember;
	const { agents, isLoading: isAgentsLoading } =
		useWorkingAgents(canManageWorkspace);

	const resolvedAgentId = agentId ?? null;
	const agent = agents.find((a) => a.agentId === resolvedAgentId) ?? null;

	const isLoading = canManageWorkspace
		? isAgentsLoading || isOrgLoading
		: isOrgLoading;

	if (isLoading) {
		return <AgentChatPanelSkeleton />;
	}

	if (!agent) {
		return (
			<TabEmptyState
				icon={Bot}
				title="Agent not found"
				description="This agent may have been removed."
			/>
		);
	}

	return (
		<AgentChatPanel
			owner={owner}
			agent={agent}
			threadId={threadId}
			initialDraft={initialDraft}
			newChatRequested={newChatRequested}
			emptyContent={emptyContent}
			preventAutoNavigate={preventAutoNavigate}
			buildThreadUrl={buildThreadUrl}
			className="min-h-0 flex-1 overflow-hidden"
		/>
	);
}
