	collapsed?: boolean;
	onToggleCollapsed?: () => void;
}) {
	const { currentOwner } = useOrgContext();
	const owner =
		currentOwner && !currentOwner.startsWith("@") ? currentOwner : null;
	const { agentId = null, threadId = null } = useParams({
		strict: false,
	}) as {
		agentId?: string;
		threadId?: string;
	};
	const { pathname } = useLocation();
	// The Builder (system agent) is shown FIRST in the Agents roster (via
	// rosterAgents), not hidden — "New chat" stays as a separate fresh-chat action.
	const { rosterAgents, workingAgents, systemAgentId, isLoading } =
		useWorkingAgents();
	const workingAgentIds = useMemo(
		() => workingAgents.map((agent) => agent.agentId),
		[workingAgents],
	);

	const { threads: recentThreads } = useRecentAgentThreads(
		owner,
		workingAgentIds.concat(systemAgentId ? [systemAgentId] : []),
		{
			enabled: !!owner && (workingAgentIds.length > 0 || !!systemAgentId),
			limit: 12,
		},
	);

	// Recent conversations across the workspace's agents, newest first.
	const recentConversations = useMemo(
		() =>
			[...recentThreads]
				.sort(
					(a, b) => (b.updatedAt ?? b.createdAt) - (a.updatedAt ?? a.createdAt),
				)
				.slice(0, 12),
		[recentThreads],
	);

	const at = (seg: string) =>
		owner ? pathname.startsWith(`/${owner}/${seg}`) : false;
	// "New chat" is context-aware; "New agent" links straight to the builder chat
	// with a prompt (see helpers — the /$owner redirect would drop search params).
	const newChat = newChatLink({ owner, agentId });
	const newAgent = newAgentLink({ owner, systemAgentId });
	// Collapsed icon-rail — only on the wide fixed sidebar (never embedded in the
	// narrow drawer, which is already a compact off-canvas panel).
	const isRail = collapsed && !embedded;

	if (isRail) {
		return (
			<aside className="fixed inset-y-0 left-0 z-40 flex w-14 flex-col items-center border-r border-border bg-sidebar-background text-sidebar-foreground">
				<div className="flex h-14 w-full items-center justify-center border-b border-sidebar-border">
					<button
						type="button"
						onClick={onToggleCollapsed}
						aria-label="Expand sidebar"
						title="Expand sidebar"
						className="flex h-9 w-9 items-center justify-center rounded-md text-sidebar-foreground/70 transition-colors hover:bg-sidebar-accent/60 hover:text-sidebar-foreground"
					>
						<PanelLeftOpen className="h-[18px] w-[18px]" />
					</button>
				</div>
				{owner ? (
					<div className="flex flex-1 flex-col gap-1 overflow-y-auto py-2">
						<RailButton
							label="New chat"
							icon={SquarePen}
							to={newChat.to}
							params={newChat.params}
							search={newChat.search}
						/>
						<RailButton
							label="Search"
							icon={Search}
							onClick={openCommandPalette}
						/>
						{(
							Object.keys(OWNER_SECTIONS) as Array<keyof typeof OWNER_SECTIONS>
						).map((key) => {
							const { icon, label, segments } = OWNER_SECTIONS[key];
							return (
								<RailButton
									key={key}
									label={label}
									active={segments.some(at)}
									icon={icon}
									to={`/$owner/${segments[0]}`}
									params={{ owner }}
								/>
							);
						})}
					</div>
				) : (
					<div className="flex-1" />
				)}
			</aside>
		);
	}

	return (
		<aside
			className={cn(
				"flex flex-col border-r border-border bg-sidebar-background text-sidebar-foreground",
				embedded ? "h-full w-full" : "fixed inset-y-0 left-0 z-40 w-[17.25rem]",
			)}
		>
			<div className="flex h-14 items-center gap-1 border-b border-sidebar-border px-2">
				<div className="min-w-0 flex-1">
					<OrganizationDropdown />
				</div>
				<button
					type="button"
					onClick={openCommandPalette}
					aria-label="Search"
					title="Search (⌘K)"
					className="flex h-8 w-8 shrink-0 items-center justify-center rounded-md text-sidebar-foreground/60 transition-colors hover:bg-sidebar-accent/60 hover:text-sidebar-foreground"
				>
					<Search className="h-[18px] w-[18px]" />
				</button>
				{!embedded && onToggleCollapsed ? (
					<button
						type="button"
						onClick={onToggleCollapsed}
						aria-label="Collapse sidebar"
						title="Collapse sidebar"
						className="flex h-8 w-8 shrink-0 items-center justify-center rounded-md text-sidebar-foreground/60 transition-colors hover:bg-sidebar-accent/60 hover:text-sidebar-foreground"
					>
						<PanelLeftClose className="h-[18px] w-[18px]" />
					</button>
				) : null}
			</div>

			{owner ? (
				<>
					<div className="flex flex-1 flex-col overflow-y-auto py-2">
						<NavRow
							to={newChat.to}
							params={newChat.params}
							search={newChat.search}
							active={false}
							icon={SquarePen}
							label="New chat"
						/>

						{/* Workspace plumbing before the agent roster — setup surfaces
						    users hit constantly sit above teammates. */}
						{(
							Object.keys(OWNER_SECTIONS) as Array<keyof typeof OWNER_SECTIONS>
						).map((key) => {
							const { icon, label, segments } = OWNER_SECTIONS[key];
							return (
								<NavRow
									key={key}
									to={`/$owner/${segments[0]}`}
									params={{ owner }}
									active={segments.some(at)}
									icon={icon}
									label={label}
								/>
							);
						})}

						<SectionHeader
							label="Agents"
							icon={<LobuMark className="h-3 w-3 text-sidebar-foreground/40" />}
							action={
								newAgent ? (
									<Link
										to={newAgent.to as "/"}
										params={newAgent.params as never}
										search={newAgent.search as never}
										aria-label="New agent"
										title="New agent"
										className="flex h-5 w-5 items-center justify-center rounded-md text-sidebar-foreground/50 transition-colors hover:bg-sidebar-accent/60 hover:text-sidebar-foreground"
									>
										<Plus className="h-3.5 w-3.5" />
									</Link>
								) : null
							}
						/>
						{isLoading ? (
							<SidebarRowsSkeleton />
						) : (
							rosterAgents.map((agent) => (
								<AgentRow
									key={agent.agentId}
									ownerSlug={owner}
									agentId={agent.agentId}
									name={agent.name}
									status={agent.status}
									selected={agentId === agent.agentId}
								/>
							))
						)}

						{recentConversations.length > 0 ? (
							<>
								<SectionHeader label="Recent" />
								{recentConversations.map((conv) => {
									const isWeb = (conv.platform ?? "web") === "web";
									// Behavior activity → the behavior's page (stitched runs).
									if (conv.platform === "behavior" && conv.behaviorId != null) {
										return (
											<NavRow
												key={`behavior:${conv.agentId}:${conv.behaviorId}`}
												to="/$owner/agents/$agentId/behaviors/$watcherId"
												params={{
													owner,
													agentId: conv.agentId,
													watcherId: String(conv.behaviorId),
												}}
												active={false}
												icon={platformIcon(conv.platform)}
												label={conv.title}
											/>
										);
									}
									// Platform conversations (Slack, …) aren't chat-routable —
									// open them read-only by raw conversation id.
									if (!isWeb) {
										return (
											<NavRow
												key={`conv:${conv.agentId}:${conv.id}`}
												to="/$owner/agents/$agentId/conversations/$conversationId"
												params={{
													owner,
													agentId: conv.agentId,
													conversationId: conv.conversationId ?? conv.id,
												}}
												active={false}
												icon={platformIcon(conv.platform)}
												label={conv.title}
											/>
										);
									}
									const threadLink = agentThreadLink(
										owner,
										conv.agentId,
										conv.id,
									);
									return (
										<NavRow
											key={`chat:${conv.agentId}:${conv.id}`}
											to={threadLink.to}
											params={threadLink.params}
											active={agentId === conv.agentId && threadId === conv.id}
											icon={MessageSquare}
											label={conv.title}
										/>
									);
								})}
							</>
						) : null}
					</div>

					<UserMenu />
				</>
			) : (
				<div className="flex flex-1 flex-col items-center justify-center px-4 text-center text-xs text-sidebar-foreground/50">
					Pick an organization to continue.
				</div>
			)}
		</aside>
	);
}
		return (
			<Link
				to={to as "/"}
				params={params as never}
				search={search as never}
				aria-label={label}
				title={label}
				className={className}
			>
				<Icon className="h-[18px] w-[18px]" />
			</Link>
		);
	}
	return (
		<button
			type="button"
			onClick={onClick}
			aria-label={label}
			title={label}
			className={className}
		>
			<Icon className="h-[18px] w-[18px]" />
		</button>
	);
}

export function AppSidebar({
	embedded = false,
	collapsed = false,
	onToggleCollapsed,
}: {
	embedded?: boolean;
	collapsed?: boolean;
	onToggleCollapsed?: () => void;
}) {
	const { currentOwner } = useOrgContext();
	const owner =
		currentOwner && !currentOwner.startsWith("@") ? currentOwner : null;
	const { agentId = null } = useParams({
		strict: false,
	}) as {
		agentId?: string;
	};
	const { pathname, search } = useLocation();
	const searchRecord = (search ?? {}) as Record<string, unknown>;
	// The Builder (system agent) is shown FIRST in the Agents roster (via
	// rosterAgents). Click an agent → chat; expand for configuration destinations.
	const { rosterAgents, systemAgentId, isLoading } = useWorkingAgents();

	// "New agent" links straight to the builder chat with a prompt (see helpers
	// — the /$owner redirect would drop search params).
	const newAgent = newAgentLink({ owner, systemAgentId });
	// Collapsed icon-rail — only on the wide fixed sidebar (never embedded in the
	// narrow drawer, which is already a compact off-canvas panel).
	const isRail = collapsed && !embedded;

	if (isRail) {
		return (
			<aside className="fixed inset-y-0 left-0 z-40 flex w-14 flex-col items-center border-r border-border bg-sidebar-background text-sidebar-foreground">
				<div className="flex h-14 w-full items-center justify-center border-b border-sidebar-border">
					<button
						type="button"
						onClick={onToggleCollapsed}
						aria-label="Expand sidebar"
						title="Expand sidebar"
						className="flex h-9 w-9 items-center justify-center rounded-md text-sidebar-foreground/70 transition-colors hover:bg-sidebar-accent/60 hover:text-sidebar-foreground"
					>
						<PanelLeftOpen className="h-[18px] w-[18px]" />
					</button>
				</div>
				{owner ? (
					<div className="flex flex-1 flex-col gap-1 overflow-y-auto py-2">
						<RailButton
							label="Search"
							icon={Search}
							onClick={openCommandPalette}
						/>
						{(Object.keys(OWNER_SECTIONS) as OwnerSectionKey[]).map((key) => {
							const section = OWNER_SECTIONS[key];
							return (
								<RailButton
									key={key}
									label={section.label}
									active={isOwnerSectionActive(
										key,
										owner,
										pathname,
										searchRecord,
									)}
									icon={section.icon}
									to={section.to}
									params={{ owner }}
									search={section.search}
								/>
							);
						})}
					</div>
				) : (
					<div className="flex-1" />
				)}
			</aside>
		);
