import { useNavigate } from "@tanstack/react-router";
import {
	type ReactNode,
	useCallback,
	useEffect,
	useMemo,
	useState,
} from "react";
import { AgentThread } from "@/components/agents/agent-thread";
import { LobuChatProvider } from "@/components/agents/lobu-chat-store";
import { agentThreadLink } from "@/lib/agent-chat-routes";
import { newThreadId } from "@/lib/agent-thread-storage";
import type { AgentItem } from "@/lib/api";
import { type AgentThreadItem, useAgentThreads } from "@/lib/api/agents";
import { cn } from "@/lib/utils";

export function AgentChatPanel({
	owner,
	agent,
	threadId,
	footer,
	emptyContent,
	className,
	initialDraft,
	newChatRequested = false,
	preventAutoNavigate,
	buildThreadUrl,
}: {
	owner: string;
	agent: AgentItem;
	threadId?: string;
	footer?: ReactNode;
	/** Home empty draft: attention timeline (etc.) above the composer. */
	emptyContent?: ReactNode;
	className?: string;
	/** Prefill the composer (from a `?prompt=` deep link). */
	initialDraft?: string;
	/** `?new` present — rotate the draft so a used composer starts truly fresh. */
	newChatRequested?: boolean;
	/** When true, do not automatically navigate to the materialized thread URL. */
	preventAutoNavigate?: boolean;
	/** Override the URL generated when materializing a draft thread. */
	buildThreadUrl?: (
		owner: string,
		agentId: string,
		threadId: string,
	) => { to: string; params: any };
}) {
	const navigate = useNavigate();
	const agentId = agent.agentId;
	const { data: threads = [] } = useAgentThreads(agentId, { orgSlug: owner });
	// The draft id is minted once, then rotated on each explicit "New chat"
	// (`?new`) so a composer that's already been typed in / materialized starts
	// truly fresh — the LobuChatProvider is keyed on this id, so rotating it
	// remounts a clean conversation. Without this, `?new` on the already-mounted
	// panel keeps the stale draft (frozen-at-mount) id and its transcript.
	const [draftThreadId, setDraftThreadId] = useState(() => newThreadId());
	const [optimisticThread, setOptimisticThread] =
		useState<AgentThreadItem | null>(null);
	// Rotate the draft when `?new` is requested, then strip `?new` from the URL.
	// Consuming-and-removing it (rather than ref-guarding a persistent level)
	// makes New chat reliably repeatable: each click re-adds `?new`, which this
	// effect handles once and clears — so clicking New chat again from the same
	// composer rotates again instead of being swallowed by a stuck flag.
	useEffect(() => {
		if (!newChatRequested || threadId) return;
		setDraftThreadId(newThreadId());
		setOptimisticThread(null);
		void navigate({
			to: ".",
			search: ((prev: Record<string, unknown>) => {
				const { new: _dropped, ...rest } = prev;
				return rest;
			}) as never,
			replace: true,
		});
	}, [newChatRequested, threadId, navigate]);

	const allThreads = useMemo(() => {
		if (!optimisticThread) return threads;
		if (threads.some((thread) => thread.id === optimisticThread.id)) {
			return threads;
		}
		return [optimisticThread, ...threads];
	}, [threads, optimisticThread]);

	const currentThread = threadId ?? draftThreadId;
	const isDraft =
		!threadId || !allThreads.some((thread) => thread.id === threadId);

	const materializeDraft = useCallback(() => {
		if (allThreads.some((thread) => thread.id === currentThread)) return;
		setOptimisticThread({
			id: currentThread,
			title: `Conversation ${allThreads.length + 1}`,
			createdAt: Date.now(),
			updatedAt: Date.now(),
		});
		// Navigate to the materialized thread. The chat layout keeps this panel
		// mounted across `/chat` → `/chat/c/$threadId`, and the provider key is
		// unchanged (materialized id === draft id), so nothing remounts.
		const link = buildThreadUrl
			? buildThreadUrl(owner, agentId, currentThread)
			: agentThreadLink(owner, agentId, currentThread);

		void navigate({
			...link,
			replace: true,
		});
	}, [allThreads, currentThread, navigate, owner, agentId, buildThreadUrl]);

	const onFirstUserMessage = useCallback(() => {
		if (isDraft && !preventAutoNavigate) materializeDraft();
	}, [isDraft, materializeDraft, preventAutoNavigate]);

	return (
		<div className={cn("flex min-h-0 flex-1 flex-col", className)}>
			<div className="flex min-h-0 flex-1 flex-col">
				<LobuChatProvider
					key={`${agentId}:${currentThread}`}
					agentId={agentId}
					workspaceSlug={owner}
					thread={currentThread}
					loadHistory={!!threadId}
					onFirstUserMessage={onFirstUserMessage}
					initialDraft={initialDraft}
				>
					<AgentThread footer={footer} emptyContent={emptyContent} />
				</LobuChatProvider>
			</div>
		</div>
	);
}

async function fetchAgentThreads(
	agentId: string,
	orgSlug: string | null | undefined,
	options?: { strict?: boolean },
): Promise<AgentThreadItem[]> {
	const res = await fetchWithTimeout(agentHistoryUrl(agentId, "/threads"), {
		credentials: "include",
		headers: orgScopedHeaders(orgSlug),
	});
	if (res.status === 401 || res.status === 403) return [];
	if (!res.ok) {
		if (options?.strict) {
			await throwIfNotOk(res, "Failed to fetch agent threads");
		}
		return [];
	}
	const data = (await res.json()) as { threads?: AgentThreadItem[] };
	return Array.isArray(data.threads) ? data.threads : [];
}

export function agentThreadsQueryOptions(
	orgSlug: string | null | undefined,
	agentId: string,
	options?: { strict?: boolean },
) {
	return {
		queryKey: ["agent-threads", orgSlug, agentId] as const,
		queryFn: () => fetchAgentThreads(agentId, orgSlug, options),
		staleTime: 15_000,
	};
}

