	const enabled =
		!!orgSlug && (agentIds?.length ?? 0) > 0 && (options?.enabled ?? true);

	const queries = useQueries({
		queries: (agentIds ?? []).map((agentId) => ({
			...agentThreadsQueryOptions(orgSlug, agentId, {
				strict: false,
				scope: "all",
			}),
			enabled,
		})),
	});

	const isLoading = enabled && queries.some((q) => q.isLoading);
	const threads = queries
		.flatMap((q, index) => {
			const agentId = agentIds?.[index];
			if (!agentId) return [];
			return (q.data ?? []).map((thread) => ({
				agentId,
				...thread,
			}));
		})
		.sort((a, b) => b.updatedAt - a.updatedAt)
		.slice(0, limit);

	return { threads, isLoading };
}

export function useAgentConfig(
	agentId?: string | null,
	options?: { enabled?: boolean },
) {
	const { slug } = getPathScope();

	return useQuery({
		queryKey: ["agent-config", slug, agentId],
		queryFn: async (): Promise<AgentSettings> => {
			const res = await fetchWithTimeout(
				agentsUrl(slug!, `/${agentId}/config`),
				{
					credentials: "include",
				},
			);
			await throwIfNotOk(res, "Failed to fetch agent config");
			return res.json() as Promise<AgentSettings>;
		},
		enabled: !!slug && !!agentId && (options?.enabled ?? true),
		staleTime: 30_000,
	});
}

export function useAgentProviderCatalog(
	agentId?: string | null,
	options?: { enabled?: boolean },
import { readFile, stat } from "node:fs/promises";
import { join, resolve } from "node:path";
import { sanitizeConversationId } from "@lobu/core";
import { filterChannelsForRequester } from "../../authz/channel-visibility.js";
import { type DbClient, getDb } from "../../db/client.js";
import {
	resolveBoundChannelRows,
	stripPlatformPrefix,
} from "../channels/bound-channels.js";
import { buildApiConversationId } from "./api-conversation-id.js";
import { listConversations } from "./conversations-store.js";
import { paginateSessionMessages } from "./session-message-page.js";
import { readSnapshotJsonl } from "./transcript-snapshot.js";

const SAFE_AGENT_ID = /^[a-zA-Z0-9_-]+$/;
const SAFE_THREAD_ID = /^[a-zA-Z0-9_-]+$/;

function isSafeAgentId(id: string): boolean {
	return SAFE_AGENT_ID.test(id);
}

function isSafeThreadId(id: string): boolean {
	return SAFE_THREAD_ID.test(id);
}

export interface AgentThreadSummary {
	/** Routing key: a thread id for web conversations (chattable), or the raw
	 *  conversation id for platform conversations (read-only). */
	id: string;
	title: string;
	createdAt: number;
	updatedAt: number;
	/** "web" for the app's own threads; "behavior" for behavior activity; otherwise
	 *  the source platform derived from the conversation id prefix (slack, …). */
	platform: string;
	/** Raw conversation id — used to read a platform conversation read-only. */
	conversationId: string;
	/** Set on `platform: "behavior"` entries — routes to the behavior's page. */
	behaviorId?: number;
}

/** `{platform}:{team}:{channel}` — team-scoped so the same channel id in two
 *  Slack workspaces never collides. `team` is "" for platforms without one. */
function channelVisibilityKey(
	platform: string,
	teamId: string | null,
	bareChannelId: string,
): string {
	return `${platform.toLowerCase()}:${teamId ?? ""}:${bareChannelId}`;
}

export interface ChannelVisibility {
	/** Team-scoped keys the requester may read (per-agent fence ∩ per-user ACL). */
	visibleKeys: Set<string>;
	/** `{platform}:{channel}` → the team ids the AGENT is bound to it in. A
	 *  channel bound in >1 team can't be disambiguated from a conversation id
	 *  alone, so it fails closed. */
	channelTeams: Map<string, Set<string>>;
}

/**
 * Which channels may THIS requester read for THIS agent — the per-agent channel
 * fence (the agent's bound channels) INTERSECTED with the per-user channel ACL
 * gate ({@link filterChannelsForRequester}), team-scoped. A platform conversation
 * is visible iff {@link isConversationVisible}. Mirrors recall's gate so a user
 * never sees a channel transcript they're not a member of.
 */
export async function resolveChannelVisibility(
	sql: DbClient,
	args: {
		organizationId: string;
		agentId: string;
		userId: string | null;
		allowNotGraphed?: boolean;
	},
): Promise<ChannelVisibility> {
	const bound = await resolveBoundChannelRows(sql, {
		organizationId: args.organizationId,
		agentId: args.agentId,
	});
	const channelTeams = new Map<string, Set<string>>();
	for (const c of bound) {
		const bare = stripPlatformPrefix(c.platform, c.channel_id);
		const pc = `${c.platform.toLowerCase()}:${bare}`;
		const set = channelTeams.get(pc) ?? new Set<string>();
		set.add(c.team_id ?? "");
		channelTeams.set(pc, set);
	}
	const visible = await filterChannelsForRequester(sql, {
		organizationId: args.organizationId,
		userId: args.userId,
		rows: bound,
		allowNotGraphed: args.allowNotGraphed,
	});
	const visibleKeys = new Set(
		visible.map((c) =>
			channelVisibilityKey(
				c.platform,
				c.team_id,
				stripPlatformPrefix(c.platform, c.channel_id),
			),
		),
	);
	return { visibleKeys, channelTeams };
}

/** Can the requester read this platform conversation (`{platform}:{channel}:{thread}`)?
 *  Fail-closed: unbound, or a channel bound in ≥2 DISTINCT REAL workspaces (can't
 *  tie the conversation to a single team), is not visible.
 *
 *  A NULL/"" team is a WILDCARD ("workspace unknown yet" — a binding written
 *  before its workspace healed from the first inbound event), NOT a distinct
 *  workspace. `team_id` is now guaranteed to be a real workspace or NULL (never a
 *  Grid enterprise id), so the gate needs zero connector knowledge: it counts
 *  distinct non-null teams and only fails closed on genuine cross-workspace
 *  ambiguity (2+ real teams). One real team + any number of NULLs resolves to
 *  that team; all-NULL resolves via the wildcard visible key. */
export function isConversationVisible(
	conversationId: string,
	vis: ChannelVisibility,
): boolean {
	const parts = conversationId.split(":");
	const platform = (parts[0] ?? "").toLowerCase();
	const channel = parts[1] ?? "";
	const teams = vis.channelTeams.get(`${platform}:${channel}`);
	if (!teams || teams.size === 0) return false; // unbound
	const realTeams = [...teams].filter((t) => t !== "");
	if (realTeams.length > 1) return false; // genuine cross-workspace ambiguity
	// One real team (NULLs are wildcards that resolve to it), or all-NULL (a
	// teamless/unknown-yet binding — resolves via the "" wildcard visible key).
	const team = realTeams[0] ?? null;
	return vis.visibleKeys.has(channelVisibilityKey(platform, team, channel));
}

async function findConversationSessionFile(
	agentId: string,
	conversationId: string,
): Promise<string | null> {
	if (!isSafeAgentId(agentId)) return null;
	const workspacesRoot = resolve("workspaces");
	const workspaceDir = resolve(workspacesRoot, agentId);
	if (!workspaceDir.startsWith(`${workspacesRoot}/`)) return null;

	const sanitized = sanitizeConversationId(conversationId);
	const sessionPath = join(
		workspaceDir,
		sanitized,
		".lobu",
		"session.jsonl",
	);
	try {
		await stat(sessionPath);
		return sessionPath;
	} catch {
		return null;
	}
}

export async function listAgentThreads(args: {
	agentId: string;
	organizationId?: string;
	userId: string;
	/** "user" (default): only the requesting user's app threads. "all": every
	 *  conversation for the agent across platforms (Slack, Telegram, …). */
	scope?: "user" | "all";
	/**
	 * Does the requester have admin access to this agent/org? Only consulted for
	 * DM conversations that the normal channel-membership path cannot admit.
	 * Defaults to false so a caller that forgets to pass it fails closed.
	 */
	isAdmin?: boolean;
}): Promise<AgentThreadSummary[]> {
	const {
		agentId,
		organizationId,
		userId,
		scope = "user",
		isAdmin = false,
	} = args;
	// No org → no tenant scope → nothing to list from the (org-keyed) entity.
	if (!organizationId) return [];

	const byKey = new Map<string, AgentThreadSummary>();

	// Owned + platform conversations come from the `conversations` entity — the
	// single listing source. This replaces the old
	// `DISTINCT ON (conversation_id) FROM agent_transcript_snapshot` derive path
	// AND the workspace-directory scan.
	//
	// This is an end-user feed, so "all" means "mine plus the channels I may
	// read" — `shared`, never the store's `admin`. Admin listing is
	// `manage_conversations`, which checks a role first.
	const rows = await listConversations({
		organizationId,
		agentId,
		scope: scope === "all" ? "shared" : "user",
		userId,
	});

	// Platform ("all" scope) rows are ACL-gated: a platform conversation is only
	// listed if its channel is in the agent's bound channels AND (for ACL-graphed
	// connections) the requester is a member — so a user never sees a channel
	// transcript they can't read.
	let channelVis: ChannelVisibility | null = null;
	if (scope === "all") {
		channelVis = await resolveChannelVisibility(getDb(), {
			organizationId,
			agentId,
			userId,
		});
	}

	for (const row of rows) {
		const at = row.lastActivityAt.getTime();
		const createdAt = row.createdAt.getTime();
		if (row.kind === "owned") {
			// Routable id is STORED (`thread_id`), never re-parsed out of the id
			// string. The migration trigger also covers writes from an old server
			// between the pre-upgrade migration and deployment replacement.
			const threadId = row.threadId;
			if (!threadId || !isSafeThreadId(threadId) || byKey.has(threadId)) {
				continue;
			}
			byKey.set(threadId, {
				id: threadId,
				title: row.title ?? `Conversation ${byKey.size + 1}`,
				createdAt,
				updatedAt: at,
				platform: "web",
				conversationId: row.conversationId,
			});
		} else if (row.kind === "platform") {
			// One entry per conversationId — that's the whole identity of a platform
			// conversation (the connection that delivered it is routing, not identity;
			// a reconnect changes it without changing the conversation). The ACL and
			// transcript read address it by conversationId alone, consistent with this.
			//
			// isConversationVisible extracts platform:channel from the id, so an
			// opaque/no-colon platform id fails closed (unlisted) — same as the prior
			// path, which only ever listed `LIKE '%:%'` platform ids. Failing closed
			// is safe; the same-channel-across-two-workspaces (Grid) case is likewise
			// handled by isConversationVisible failing closed on team ambiguity.
			if (byKey.has(row.conversationId)) continue;
			// Some DMs are explicitly bound (for example Preview `/link`) and must
			// keep the existing channel-fence path. Admin access is the safe bypass
			// for an unbound DM, whose correspondent cannot be mapped portably to a
			// Lobu user. `isDirect` null (unknown) also keeps the channel fence and
			// stays fail-closed.
			if (
				!(row.isDirect === true && isAdmin) &&
				channelVis &&
				!isConversationVisible(row.conversationId, channelVis)
			) {
				continue;
			}
			byKey.set(row.conversationId, {
				id: row.conversationId,
				title: row.title ?? row.conversationId,
				createdAt,
				updatedAt: at,
				// Label from the EXPLICIT stored platform, not by parsing the id — an
				// opaque/no-colon platform id (e.g. gchat spaces_A_threads_B) would
				// otherwise mislabel as "web".
				platform: row.platform,
				conversationId: row.conversationId,
			});
		}
	}

	// Behavior activity comes from bounded `watchers` config rather than
	// aggregating append-only transcript history. A Behavior is not a conversation,
	// so it keeps the existing `watcher_<id>` route key without a `conversations`
	// row. Reading status and name live also drops archived rows immediately.
	if (scope === "all") {
		const sql = getDb();
		const behaviorRows = await sql<{
			id: number;
			name: string | null;
			last_run_completed_at: Date;
		}>`
      SELECT id, name, last_run_completed_at
      FROM public.watchers
      WHERE organization_id = ${organizationId}
        AND agent_id = ${agentId}
        AND status = 'active'
        AND last_run_completed_at IS NOT NULL
      ORDER BY last_run_completed_at DESC
    `;
		for (const row of behaviorRows) {
			// `watcher_<id>` is the key the panel has always rendered and routed on.
			const key = `watcher_${row.id}`;
			const at = row.last_run_completed_at.getTime();
			byKey.set(key, {
				id: key,
				title: row.name ?? `Behavior ${row.id}`,
				// Preserves the derived contract: a Behavior entry represents latest
				// activity, so both timestamps track the last completed run.
				createdAt: at,
				updatedAt: at,
				platform: "behavior",
				conversationId: key,
				behaviorId: row.id,
			});
		}
	}

	return [...byKey.values()].sort((a, b) => b.updatedAt - a.updatedAt);
}

/**
 * Read one conversation's messages by its RAW conversation id (e.g. a platform
 * thread `slack:{channel}:{ts}`). Read-only — used to render platform
 * conversations that aren't routable through the app chat composer.
 */
export async function readConversationMessages(args: {
	agentId: string;
	organizationId: string;
	conversationId: string;
	cursor: string;
	limit: number;
}) {
	const { agentId, organizationId, conversationId, cursor, limit } = args;
	const jsonl = await readSnapshotJsonl({
		agentId,
		organizationId,
		conversationId,
	});
	if (jsonl === null) {
		return {
			messages: [],
			nextCursor: null,
			hasMore: false,
			sessionId: conversationId,
			threadId: conversationId,
		};
	}
	return {
		...paginateSessionMessages(jsonl, cursor, limit, {
			excludeVerbose: true,
			sessionIdFallback: conversationId,
		}),
		threadId: conversationId,
	};
}

export async function loadConversationTranscriptJsonl(
	agentId: string,
	organizationId: string | undefined,
	conversationId: string,
): Promise<string | null> {
	const fromDb = await readSnapshotJsonl({
		agentId,
		organizationId,
		conversationId,
	});
	if (fromDb !== null) return fromDb;

	const sessionPath = await findConversationSessionFile(
		agentId,
		conversationId,
	);
	if (!sessionPath) return null;
	return readFile(sessionPath, "utf-8");
}

export async function readThreadMessages(args: {
	agentId: string;
	threadId: string;
	cursor: string;
	limit: number;
	organizationId?: string;
	userId: string;
}) {
	const { agentId, threadId, cursor, limit, organizationId, userId } = args;
	const conversationId = buildApiConversationId({
		agentId,
		userId,
		organizationId,
		threadId,
	});

	const content = await loadConversationTranscriptJsonl(
		agentId,
		organizationId,
		conversationId,
	);
	if (content === null) {
		return {
			messages: [],
			nextCursor: null,
			hasMore: false,
			sessionId: conversationId,
			threadId,
		};
	}

	return {
		...paginateSessionMessages(content, cursor, limit, {
			excludeVerbose: true,
			sessionIdFallback: conversationId,
		}),
		threadId,
	};
}

	async function proxyOrFallback<T>(
		agentId: string,
		workerPath: string,
		fallback: (agentId: string) => Promise<T>
	): Promise<{ data: T; proxied: boolean } | null> {
		const { resolvedAgentId } = await resolveActiveAgent(agentId);
		const httpUrl = connectionManager?.getHttpUrl(resolvedAgentId);

		if (httpUrl) {
			try {
				const response = await fetch(`${httpUrl}${workerPath}`, {
					signal: AbortSignal.timeout(5000),
				});
				if (response.ok) {
					return { data: (await response.json()) as T, proxied: true };
				}
			} catch {
				// Worker HTTP not reachable, fall through to file read
			}
		}

		try {
			return { data: await fallback(resolvedAgentId), proxied: false };
		} catch (e) {
			logger.debug("Session file fallback failed", {
				error: e,
				agentId: resolvedAgentId,
			});
			return null;
		}
	}

	app.get("/threads", async (c) => {
		const scope = await getAuthorizedAgentScope(c);
		if (!scope) return errorResponse(c, "Unauthorized", 401);

		// `?scope=all` widens the list to every conversation for the agent across
		// platforms (Slack, Telegram, …), not just the requesting user's threads.
		const listScope = c.req.query("scope") === "all" ? "all" : "user";
		// DM conversations gate on explicit admin access, not channel membership.
		// Resolve the org-role half only for the widened list; the existing
		// platform-admin bypass is already carried on the authorized scope.
		const isAdmin =
			listScope === "all" && scope.organizationId
				? scope.isAdmin ||
					isAdminOrOwnerRole(
						await getCachedMembershipRole(scope.organizationId, scope.userId),
					)
				: false;
		const threads = await listAgentThreads({
			agentId: scope.agentId,
			organizationId: scope.organizationId,
			userId: scope.userId,
			scope: listScope,
			isAdmin,
		});
		return c.json({ threads });
	});

	app.get("/threads/:threadId/messages", async (c) => {
		const scope = await getAuthorizedAgentScope(c);
		if (!scope) return errorResponse(c, "Unauthorized", 401);

		const threadId = c.req.param("threadId") || "";
		if (!isSafeThreadId(threadId)) {
			return errorResponse(c, "Invalid thread id", 400);
		}

		const cursor = c.req.query("cursor") || "";
		const limit = Math.min(parseInt(c.req.query("limit") || "200", 10), 200);

		const data = await readThreadMessages({
			agentId: scope.agentId,
			threadId,
			cursor,
			limit,
			organizationId: scope.organizationId,
			userId: scope.userId,
		});

		// Re-sign tokenless attachment references in user messages so their
		// download links are valid for this session (the transcript stores them
		// tokenless and portable; see `resignFileRefs`).
		if (artifactStore && publicGatewayUrl && Array.isArray(data.messages)) {
			data.messages = data.messages.map((message) =>
				message.role === "user"
					? {
							...message,
							content: resignFileRefs(
								message.content,
								artifactStore,
								publicGatewayUrl
							),
						}
					: message
			);
		}

		// Replay durable interaction cards the transcript doesn't carry (today the
		// builder's manage_agents write-gate approval). Reconstruct the session
		// conversationId the worker stamped (same parts), then read the still-
		// pending approval events. Self-cleaning: a resolved approval is
		// superseded out of current_event_records. Without this the interactive
		// approval card is lost on reload — only the model's text + link survive.
		let interactions: HistoryInteraction[] = [];
		if (scope.organizationId) {
			const conversationId = buildApiConversationId({
				agentId: scope.agentId,
				userId: scope.userId,
				organizationId: scope.organizationId,
				threadId,
			});
			const rows = await getDb()<{
				event_id: number;
				run_id: number;
				action: string | null;
				proposal: Record<string, unknown> | null;
				current: Record<string, unknown> | null;
				fields: Record<string, unknown> | null;
				attribution: string | null;
				resource_kind: string | null;
				reason: string | null;
				tool: string | null;
			}>`
				SELECT id AS event_id,
				       run_id,
				       metadata->>'action' AS action,
				       metadata->'proposal' AS proposal,
				       metadata->'current' AS current,
				       -- entity_field_change (manage_entity) carries the
				       -- human-owned-field diff + attribution; manage_agents
				       -- leaves these null and replays its agent-row proposal.
				       metadata->'fields' AS fields,
				       metadata->>'attribution' AS attribution,
				       metadata->>'resourceKind' AS resource_kind,
				       metadata->>'reason' AS reason,
				       metadata->>'tool' AS tool
				FROM current_event_records
				WHERE organization_id = ${scope.organizationId}
				  AND interaction_type = 'approval'
				  AND interaction_status = 'pending'
				  AND metadata->>'conversationId' = ${conversationId}
				ORDER BY run_id
			`;
			interactions = rows.map((r) => {
				// Normalize the legacy stored `resource_kind: "watcher"` to the public
				// "behavior" value so old and new events emit one canonical discriminator.
				const rawResourceKind =
					r.resource_kind ??
					(r.tool === "manage_behaviors"
						? "behavior"
						: r.tool === "manage_agents"
							? "agent"
							: r.tool === "entity_field_change" || r.tool === "entity_change"
								? "entity"
								: null);
				const resourceKind =
					rawResourceKind === "watcher" ? "behavior" : rawResourceKind;
				// manage_behaviors stores proposal as `{ args }`; SPA expects flat fields.
				const rawProposal = r.proposal ?? null;
				const proposal =
					resourceKind === "behavior" &&
					rawProposal &&
					typeof rawProposal === "object" &&
					(rawProposal as { args?: unknown }).args &&
					typeof (rawProposal as { args: unknown }).args === "object"
						? (rawProposal as { args: Record<string, unknown> }).args
						: rawProposal;
				return {
					type: "tool-approval" as const,
					eventId: Number(r.event_id),
					runId: Number(r.run_id),
					action: r.action,
					proposal,
					current: r.current ?? null,
					fields: r.fields ?? null,
					attribution: r.attribution ?? null,
					resourceKind,
					reason: r.reason ?? null,
				};
			});
			const errorInteraction = await readLatestAgentErrorInteraction(
				scope.organizationId,
				conversationId
			);
			if (errorInteraction) interactions.push(errorInteraction);

			// Replay the conversation's current suggestion chips (a live-streamed
			// `complete` payload carries them, but they're lost on reload without
			// this). Separate branch — NOT the approval query, which maps every row
			// to tool-approval.
			const currentSuggestion = await readCurrentSuggestion(
				scope.organizationId,
				conversationId
			);
			if (currentSuggestion) {
				interactions.push({
					type: "suggestion",
					prompts: currentSuggestion.prompts,
				});
			}
		}
		return c.json({ ...data, interactions });
	});

	// Read ANY conversation the listing handed out, by its STORED id.
	//
	// The fence comes from the `conversations` row, not from the shape of the id.
	// Previously this route accepted only `{platform}:{...}` ids and the owned
	// read path re-derived its id from the caller's own userId — which meant an
	// owned conversation could be listed and then never opened, because no
	// handler accepted the id the listing returned.
	app.get("/conversations/:conversationId/messages", async (c) => {
		const scope = await getAuthorizedPlatformConversationScope(c);
		if (!scope) return errorResponse(c, "Unauthorized", 401);

		const conversationId = decodeURIComponent(
			c.req.param("conversationId") || ""
		);
		// Platform ids carry colons; owned ids are underscore-delimited. Both are
		// alnum plus `._:-`, so one charset covers them without implying a shape.
		if (!conversationId || !/^[a-zA-Z0-9._:-]+$/.test(conversationId)) {
			return errorResponse(c, "Invalid conversation id", 400);
		}

		// Fail closed (404, not 403) throughout, so an unauthorized id is
		// indistinguishable from a non-existent one.
		// A row is the only thing that can prove a conversation is OWNED. Platform
		// transcripts are readable without one — federated channel ACL admits a
		// non-owner org member whose access comes from the channel, not from a
		// conversations row — so a miss falls through to the channel gate rather
		// than 404ing, which is what the row-mandatory version got wrong.
		const row = await findConversationById({
			organizationId: scope.organizationId,
			agentId: scope.agentId,
			conversationId,
		});

		if (row?.kind === "owned") {
			// An owned conversation belongs to the user who started it. Admins keep
			// the bypass the scope resolver already granted them.
			if (!scope.isAdmin && row.userId !== scope.userId) {
				return errorResponse(c, "Conversation not found", 404);
			}
		} else {
			let bypassChannelFence = false;
			if (row?.isDirect === true) {
