		ownerRoute.addChildren([
			createRoute({ getParentRoute: () => ownerRoute, path: "/" }),
			memoryRoute,
			createRoute({ getParentRoute: () => ownerRoute, path: "connectors" }),
			agentRoute.addChildren([
				createRoute({ getParentRoute: () => agentRoute, path: "chat" }),
				createRoute({ getParentRoute: () => agentRoute, path: "behaviors" }),
				createRoute({ getParentRoute: () => agentRoute, path: "skills" }),
				createRoute({ getParentRoute: () => agentRoute, path: "guardrails" }),
				createRoute({ getParentRoute: () => agentRoute, path: "settings" }),
			]),
		]),
	]);
	const router = createRouter({
		routeTree,
		history: createMemoryHistory({ initialEntries: [path] }),
	});
	const queryClient = new QueryClient({
		defaultOptions: { queries: { retry: false } },
	});
	render(
		<QueryClientProvider client={queryClient}>
			{/* biome-ignore lint/suspicious/noExplicitAny: synthetic test router */}
			<RouterProvider router={router as any} />
		</QueryClientProvider>,
	);
	// Both agent rows mounting proves the router matched and the tree settled.
	await screen.findByText("Alpha");
	await screen.findByText("Beta");
}

describe("AppSidebar site map", () => {
