		expect(screen.queryByRole("link", { name: "Configure" })).toBeNull();
		expect(screen.queryByRole("link", { name: "New chat" })).toBeNull();
	});

	it("links Connectors straight to /connectors", async () => {
		await renderSidebarAt("/test-org/connectors");

		expect(screen.getByRole("link", { name: "Connectors" })).toHaveAttribute(
			"href",
			"/test-org/connectors",
		);
	});

	// Activity = the Events stream page; Memory = the entity schema.
	it("links Activity to /activity and Memory to /memory", async () => {
		await renderSidebarAt("/test-org/memory");

		expect(screen.getByRole("link", { name: "Activity" })).toHaveAttribute(
			"href",
			"/test-org/activity",
		);
		expect(screen.getByRole("link", { name: "Memory" })).toHaveAttribute(
			"href",
			"/test-org/memory",
		);
		// This row was "Models" (collided with model *providers* under Connect),
		// then "Entities". Neither old label may survive anywhere in the nav.
		expect(screen.queryByRole("link", { name: "Models" })).toBeNull();
		expect(screen.queryByRole("link", { name: "Entities" })).toBeNull();
	});

	it("expands Context to the entity types, each with its record count", async () => {
		await renderSidebarAt("/test-org/memory");

		const company = await screen.findByRole("link", { name: /Company/ });
		// `type` is the scope key memoryScopeSearch writes — an entityType-style
		// key would link somewhere the Entities view does not scope on.
		expect(company).toHaveAttribute("href", "/test-org/memory?type=company");
		expect(company).toHaveTextContent("12");

		// Zero renders rather than being hidden: an explicit 0 distinguishes an
		// empty type from a count that has not loaded.
		expect(await screen.findByRole("link", { name: /Goal/ })).toHaveTextContent(
			"0",
		);
	});

	// The rail and scope bar filter `$…` types out. Context must not: a young
	// workspace whose only type is `$member` would otherwise show a Context row
	// that looks expandable but has nothing under it.
	it("lists system types under Context", async () => {
		await renderSidebarAt("/test-org/memory");

		expect(await screen.findByRole("link", { name: /Member/ })).toHaveAttribute(
			"href",
			"/test-org/memory?type=%24member",
		);
	});

	it("collapses Context when the entities view is not active", async () => {
		await renderSidebarAt("/test-org/connectors");

		expect(screen.queryByRole("link", { name: /Company/ })).toBeNull();
	});

	// The scoped type takes the highlight off the parent Context row. Reading
	// `entityType` instead of `type` here silently highlights nothing, and an
	// href-only assertion cannot catch that — the links are correct either way.
	it("highlights the scoped type's row, not the Context row", async () => {
		await renderSidebarAt("/test-org/memory?type=company");

		const company = await screen.findByRole("link", { name: /Company/ });
		const goal = await screen.findByRole("link", { name: /Goal/ });
		// Match the class list, not a substring: every inactive row carries
		// `hover:bg-sidebar-accent/60`, which a `toContain` would match too.
		expect(company).toHaveClass("bg-sidebar-accent");
		expect(goal).not.toHaveClass("bg-sidebar-accent");
	});

	it("keeps the type highlighted while browsing one of its records", async () => {
		await renderSidebarAt("/test-org/memory?entity=company/acme");

		expect(await screen.findByRole("link", { name: /Company/ })).toHaveClass(
			"bg-sidebar-accent",
		);
	});

	// Expanded, Context is the parent of the type rows — but it carried their
	// exact weight and indent, so browsing a type (which moves the highlight off
	// it) left "Memory" reading as one more entity type in the list.
	it("recedes the Context label while a type below it is being browsed", async () => {
		await renderSidebarAt("/test-org/memory?type=company");

		const memory = await screen.findByRole("link", { name: "Memory" });
		const label = memory.querySelector("span:not(:first-child)");
		const company = await screen.findByRole("link", { name: /Company/ });

		expect(label).toHaveClass("text-sidebar-foreground/50");
		// The distinction only exists if the child did NOT also recede.
		expect(company.className).not.toContain("text-sidebar-foreground/50");
	});

	it("keeps Context at full weight when the map itself is the open page", async () => {
		// Being the current page outranks being a parent: the row still carries
		// the highlight here, and grey-on-accent would read as disabled.
		await renderSidebarAt("/test-org/memory");

		const memory = await screen.findByRole("link", { name: "Memory" });
		expect(memory.querySelector("span:not(:first-child)")).not.toHaveClass(
			"text-sidebar-foreground/50",
		);
	});

	it("keeps Context at full weight while collapsed", async () => {
		// Collapsed there are no children to be confused with, and a greyed row
		// with nothing under it just looks disabled.
		await renderSidebarAt("/test-org/connectors");

		const memory = await screen.findByRole("link", { name: "Memory" });
		expect(memory.querySelector("span:not(:first-child)")).not.toHaveClass(
			"text-sidebar-foreground/50",
		);
	});
});
