/**
 * Collapse override for a route-driven collapsible: the route decides the
 * default (active ⇒ open), a manual toggle wins until the route context
 * changes again. Implemented with the render-time state-reset idiom so a
 * navigation into/out of the group re-applies the route default.
 */
function useRouteDefaultOpen(routeActive: boolean): {
	open: boolean;
	setOpen: (open: boolean) => void;
} {
	const [override, setOverride] = useState<boolean | null>(null);
	const [lastRouteActive, setLastRouteActive] = useState(routeActive);
	if (routeActive !== lastRouteActive) {
		setLastRouteActive(routeActive);
		setOverride(null);
	}
	return { open: override ?? routeActive, setOpen: setOverride };
}

/** Chevron glyph for a collapsible nav group (label the wrapping button). */
function GroupChevron({ open }: { open: boolean }) {
