/**
 * One MCP client session (ChatGPT, Claude, CLI …) — the org-level activity
 * grouping served from `/api/{org}/clients/sessions`, derived from the
 * tool-invocation audit ledger and stamped approval events.
 */
export interface ClientSessionItem {
	sessionId: string;
	clientId: string | null;
	clientName: string | null;
	userId: string | null;
	agentId: string | null;
	firstCallAt: number;
	lastCallAt: number;
	callCount: number;
	failedCount: number;
	tools: string[];
	pendingInteractionCount: number;
}

export function useClientSessions(options?: {
	enabled?: boolean;
	limit?: number;
	refetchInterval?: number;
}) {
	const { slug } = getPathScope();
	const limit = options?.limit ?? 20;

	return useQuery({
		queryKey: ["client-sessions", slug, limit],
		queryFn: async (): Promise<ClientSessionItem[]> => {
			const res = await fetchWithTimeout(
				`${API_URL}/api/${slug}/clients/sessions?limit=${limit}`,
				{ credentials: "include" },
			);
			await throwIfNotOk(res, "Failed to load client sessions");
			const data = (await res.json()) as { sessions?: ClientSessionItem[] };
			return data.sessions ?? [];
		},
		enabled: !!slug && (options?.enabled ?? true),
		staleTime: 15_000,
		refetchInterval: options?.refetchInterval,
	});
}

