/**
 * Lists guardrails registered with the gateway for an agent. Resolves to
 * `null` when the registry is unavailable — the UI renders a coming-soon
 * state instead of treating it as an empty registry.
 */
export function useGuardrailsCatalog(
	agentId?: string | null,
	options?: { enabled?: boolean },
) {
	const { slug } = getPathScope();
	return useQuery<GuardrailCatalogItem[] | null>({
		queryKey: ["guardrails-catalog", slug, agentId],
		queryFn: async () => {
			const res = await fetchWithTimeout(
				`${API_URL}/api/${slug}/installed/agents/${agentId}/installed?kinds=guardrails`,
				{ credentials: "include" },
			);
			if (res.status === 404) return null;
			await throwIfNotOk(res, "Failed to fetch guardrails");
			const data = (await res.json()) as {
				installed?: {
					guardrails?: {
						items?: Array<{
							id: string;
							name: string;
							detail?: Record<string, unknown>;
						}>;
					};
				};
			};
			const items = data.installed?.guardrails?.items;
			if (!items) return null;
			return items.map((item) => ({
				name: item.name,
				stages: (item.detail?.stages as GuardrailStage[] | undefined) ?? [],
			}));
		},
		enabled: !!slug && !!agentId && (options?.enabled ?? true),
		staleTime: 60_000,
	});
}

