/** Format entity path segments as `type/slug/…` for the `?entity=` scope. */
export function entityPathToBrowsePath(segments: EntityPathSegment[]): string {
	return segments
		.map((segment) => `${segment.entity_type}/${segment.slug}`)
		.join("/");
}

/**
 * The parsed shape of a `/memory/$` splat: the entity type slug (first segment)
 * and, for entity detail, the full path. A bare `/memory` (no splat) parses to
 * `{ typeSlug: undefined }` — the memory home.
 */
export type MemorySplat = {
	/** Raw (still URL-encoded) first path segment — the entity type. */
	typeSegment?: string;
	/** Full path after `/memory/` — `type` or `type/slug/...`. */
	path?: string;
	/** True when the splat addresses a single entity (has a slug after the type). */
	isEntityDetail: boolean;
};

export function parseMemorySplat(splat: string | undefined): MemorySplat {
	const trimmed = (splat ?? "").replace(/^\/+|\/+$/g, "");
	if (!trimmed) return { isEntityDetail: false };
	const segments = trimmed.split("/");
	return {
		typeSegment: segments[0],
		path: trimmed,
		isEntityDetail: segments.length > 1,
	};
}

/**
 * A single-scope Memory selection. These variants are mutually exclusive.
 */
export type MemoryScope =
	| { kind: "type"; slug: string }
	| { kind: "entity"; path: string };

/**
 * Set one in-place scope on `/memory` (entities) and clear the other scopes.
 */
export function memoryScopeSearch(ownerSlug: string, scope: MemoryScope) {
	return {
		to: "/$owner/memory" as const,
		params: { owner: ownerSlug },
		search: pruneSearch({
			type: scope.kind === "type" ? scope.slug : undefined,
			entity: scope.kind === "entity" ? scope.path : undefined,
		}) as Record<string, string | undefined>,
	};
}

/**
 * Additive scope for the Activity page: apply a filter patch while preserving
 * sibling event filters already in the URL. This is what makes the Activity
 * toolbar dropdowns COMBINABLE (type + connection_ids + feed_ids + agent AND
 * together) rather than mutually exclusive like `memoryScopeSearch`. A patch
 * value of `undefined` clears that key.
 */
export function memoryEventsFilterSearch(
	ownerSlug: string,
	currentSearch: Record<string, unknown>,
	patch: Record<string, string | undefined>,
) {
	return {
		to: "/$owner/activity" as const,
		params: { owner: ownerSlug },
		search: pruneSearch({
			...currentSearch,
			...patch,
		}) as Record<string, string | undefined>,
	};
}

/** Scope to an entity type (`?type=`). */
export function memoryBrowseTypeSearch(
	ownerSlug: string,
	entityTypeSlug: string,
) {
	return memoryScopeSearch(ownerSlug, { kind: "type", slug: entityTypeSlug });
}

/** Scope to a single entity (`?entity=<type>/<slug>`). */
export function memoryBrowseEntitySearch(
	ownerSlug: string,
	segments: EntityPathSegment[],
) {
	return memoryScopeSearch(ownerSlug, {
		kind: "entity",
		path: entityPathToBrowsePath(segments),
	});
}

/** The `?entity=<type>/<slug>` scope, if any (type segments decoded). */
export function parseEntityScope(
	search: Record<string, unknown>,
): string | undefined {
	const raw =
		typeof search.entity === "string" && search.entity.trim()
			? search.entity.trim()
			: undefined;
	return raw ? decodeEntityBrowsePath(raw) : undefined;
}

function pickMemoryCreate(search: Record<string, unknown>): string | undefined {
	return search.create === true || search.create === "true"
		? "true"
		: undefined;
}

/** The normalized `?connection_ids=` scope, accepting router-coerced numbers. */
export function parseConnectionScope(
	search: Record<string, unknown>,
): string | undefined {
	const raw = search.connection_ids;
	if (typeof raw === "number") return String(raw);
	return typeof raw === "string" && raw.trim() ? raw.trim() : undefined;
}

function pickAgentScope(search: Record<string, unknown>): string | undefined {
	const raw = search.agent ?? search.agent_id;
	return typeof raw === "string" && raw.trim() ? raw.trim() : undefined;
}

/** The `?agent=<agentId>` scope, if any. */
