/**
 * A connected MCP client, rendered through the connectors detail route as
 * `client:{id}`.
 *
 * This page carries Revoke, which is the reason the standalone
 * `/connectors/apps` page could be deleted in the same change rather than
 * waiting on Recent: revoking a grant had exactly one home in the SPA, and it
 * moved here.
 *
 * Identity deliberately shows BOTH names. `client_name` is what the app
 * registered as and is the row's identity; `clientInfo.name` names the process
 * driving the connection. Before they were separated, Owletto for Mac and
 * Claude both rendered as "claude-code" — two rows, same title, and no way to
 * tell which grant Revoke would kill.
 */
export function ClientDetail({
	ownerSlug,
	clientId,
}: {
	ownerSlug: string;
	clientId: string;
}) {
	const { orgContext } = useOrgContext();
	const { isAdmin } = useMembers(orgContext.organizationId);
	const { data: clients = [], isLoading } = useConnectedClients(null);
	const revoke = useRevokeMcpClient();
	const [confirming, setConfirming] = useState(false);

	const group = useMemo(
		() => groupClients(clients).find((g) => g.clientId === clientId),
		[clients, clientId],
	);
	// The raw registrations behind the group — each is a separate OAuth grant.
	const registrations = useMemo(
		() => clients.filter((c) => group?.clientIds.includes(c.id)),
		[clients, group],
	);

	if (isLoading) {
		return (
			<ConnectorPageColumn className="space-y-4">
				<div className="flex items-center gap-2">
					<Skeleton className="h-6 w-6 rounded" />
					<Skeleton className="h-5 w-40" />
				</div>
				<Skeleton className="h-24 w-full rounded-lg" />
			</ConnectorPageColumn>
		);
	}

	if (!group) {
		return (
			<ConnectorPageColumn className="space-y-3">
				<p className="text-sm text-muted-foreground">
					This app isn't connected to this workspace, so its details aren't
					available.
				</p>
				<Link
					to="/$owner/connectors"
					params={{ owner: ownerSlug }}
					search={{}}
					className="text-sm text-primary hover:underline"
				>
					Back to connectors
				</Link>
			</ConnectorPageColumn>
		);
	}

	const primary = registrations[0];
	const redirectUris = (primary?.details?.redirectUris ?? []) as string[];
