function sessionJsonl(text: string): string {
	return [
		JSON.stringify({
			type: "session",
			version: 3,
			id: "s",
			timestamp: "2026-06-28T00:00:00Z",
			cwd: "/w",
		}),
		JSON.stringify({
			type: "message",
			id: "u1",
			parentId: null,
			timestamp: "2026-06-28T00:00:01Z",
			message: { role: "user", content: [{ type: "text", text }] },
		}),
	].join("\n");
}

