/** Start response, discriminated by `mode`. authorization-code (Claude) returns
 *  a redirect URL to open; device-code (ChatGPT) returns a user code to show. */
export type AgentProviderOAuthStartResponse =
	| { mode: "redirect"; authorizeUrl: string }
	| {
			mode: "device";
			userCode: string;
			deviceAuthId: string;
			interval: number;
			verificationUrl: string;
	  };

/** Complete response. Device polls return `pending` until the user authorizes. */
export interface AgentProviderOAuthCompleteResponse {
	status: "pending" | "success";
