}

// AgentSkillConfig is the canonical SkillConfig from @lobu/core (the TypeBox
// schema's Static<> in contracts/agent-settings.ts). Re-exported under the
// local name so existing imports keep resolving. The schema is a superset of
// the hand-written shape that used to live here (it also carries
// modelPreference/thinkingLevel); all fields owletto reads are
// present, so this is a safe widening.
export type AgentSkillConfig = SkillConfig;

export interface AgentSkillsCatalogItem {
	skillId: string;
