}

// AgentSettings is the canonical shape from @lobu/core (derived from
// AgentSettingsStoredSchema via Static<>). Re-exported under the local name so
// existing imports keep resolving. The hand-written copy that lived here had
// drifted: `models` was required (server treats undefined as allow-all),
// `sandboxId` was `string | null` (store collapses both to null), it carried
// a dead `mcpServers` field (zero references), and it was missing
// `preApprovedTools`. Importing the contract kills the duplicate so the two
// can never drift again.
//
// `authProfiles` is layered on here (separate-store: Postgres keeps it
// elsewhere, GET merges dynamically) — matches the core AgentSettings shape.
export type AgentSettings = AgentSettingsCore;

// GuardrailStage is the canonical union from @lobu/core (exported via the
// guardrails module). Imported for local use AND re-exported under the local
// barrel so the ~5 UI files importing it from '@/lib/api' resolve to one
// definition. Core's GuardrailStageSchema is _StageCheck-guarded against
// this same union.
import type { GuardrailStage } from "@lobu/core";

export type { GuardrailStage };

// AgentInlineGuardrail is the canonical shape from @lobu/core (the schema's
// Static<>). Re-exported under the local name so existing imports resolve.
export type AgentInlineGuardrail = AgentInlineGuardrailCore;

export interface GuardrailCatalogItem {
	/** Stable identifier — matches the name registered in `GuardrailRegistry`. */
	name: string;
	/**
	 * Every stage this guardrail is registered at. A name is the unit of
	 * configuration (enabling it arms all of its stages), so a single catalog
