export function useAgentThreadMessages(
	agentId?: string | null,
	threadId?: string | null,
	options?: { enabled?: boolean; orgSlug?: string | null },
) {
	const { slug } = getPathScope();
	const orgSlug = options?.orgSlug ?? slug;

	return useQuery({
		queryKey: ["agent-thread-messages", orgSlug, agentId, threadId],
		queryFn: async (): Promise<ThreadHistory> => {
			const res = await fetchWithTimeout(
				agentHistoryUrl(agentId ?? "", `/threads/${threadId}/messages`),
				{
					credentials: "include",
					headers: orgScopedHeaders(orgSlug),
				},
			);
			if (res.status === 401 || res.status === 403)
				return { messages: [], interactions: [] };
			await throwIfNotOk(res, "Failed to fetch thread messages");
			const data = (await res.json()) as {
				messages?: AgentThreadMessage[];
				interactions?: ThreadInteraction[];
			};
			return {
				messages: Array.isArray(data.messages) ? data.messages : [],
				interactions: Array.isArray(data.interactions) ? data.interactions : [],
			};
		},
		enabled: !!orgSlug && !!agentId && !!threadId && (options?.enabled ?? true),
		staleTime: 5_000,
	});
}

