									to={section.to}
									params={{ owner }}
									search={section.search}
								/>
							);
						})}
					</div>
				) : (
					<div className="flex-1" />
				)}
			</aside>
		);
	}

	return (
		<aside
			className={cn(
				"flex flex-col border-r border-border bg-sidebar-background text-sidebar-foreground",
				embedded ? "h-full w-full" : "fixed inset-y-0 left-0 z-40 w-[17.25rem]",
			)}
		>
			<div className="flex h-14 items-center gap-1 border-b border-sidebar-border px-2">
				<div className="min-w-0 flex-1">
					<OrganizationDropdown />
				</div>
				<button
					type="button"
					onClick={openCommandPalette}
					aria-label="Search"
					title="Search (⌘K)"
					className="flex h-8 w-8 shrink-0 items-center justify-center rounded-md text-sidebar-foreground/60 transition-colors hover:bg-sidebar-accent/60 hover:text-sidebar-foreground"
				>
					<Search className="h-[18px] w-[18px]" />
				</button>
				{!embedded && onToggleCollapsed ? (
					<button
						type="button"
						onClick={onToggleCollapsed}
						aria-label="Collapse sidebar"
						title="Collapse sidebar"
						className="flex h-8 w-8 shrink-0 items-center justify-center rounded-md text-sidebar-foreground/60 transition-colors hover:bg-sidebar-accent/60 hover:text-sidebar-foreground"
					>
						<PanelLeftClose className="h-[18px] w-[18px]" />
					</button>
				) : null}
			</div>

			{owner ? (
				<>
					<div className="flex flex-1 flex-col overflow-y-auto py-2">
						{/* Site map: Activity (events), Connect, Memory (entities).
						    Then the agent roster — agent row = chat. */}
						{(Object.keys(OWNER_SECTIONS) as OwnerSectionKey[]).map((key) => {
							const section = OWNER_SECTIONS[key];
							const active = isOwnerSectionActive(key, owner, pathname);
							// Context carries the workspace's entity types as children,
							// so it is a collapsible group rather than a plain row.
							if (key === "context") {
								return (
									<ContextGroup
										key={key}
										ownerSlug={owner}
										active={active}
										searchRecord={searchRecord}
									/>
								);
							}
							return (
								<NavRow
									key={key}
									to={section.to}
									params={{ owner }}
									search={section.search}
									active={active}
									icon={section.icon}
									label={section.label}
								/>
							);
						})}

						<SectionHeader
							label="Agents"
							icon={<LobuMark className="h-3 w-3 text-sidebar-foreground/40" />}
							action={
								newAgent ? (
									<Link
										to={newAgent.to as "/"}
										params={newAgent.params as never}
										search={newAgent.search as never}
										aria-label="New agent"
										title="New agent"
										className="flex h-5 w-5 items-center justify-center rounded-md text-sidebar-foreground/50 transition-colors hover:bg-sidebar-accent/60 hover:text-sidebar-foreground"
									>
										<Plus className="h-3.5 w-3.5" />
									</Link>
								) : null
							}
						/>
						{isLoading ? (
							<SidebarRowsSkeleton />
