							rosterAgents.map((agent) => (
								<AgentRow
									key={agent.agentId}
									ownerSlug={owner}
									agentId={agent.agentId}
									name={agent.name}
									status={agent.status}
									selected={agentId === agent.agentId}
								/>
							))
						)}
					</div>

					<UserMenu />
				</>
			) : (
				<div className="flex flex-1 flex-col items-center justify-center px-4 text-center text-xs text-sidebar-foreground/50">
					Pick an organization to continue.
				</div>
			)}
		</aside>
	);
