import { type FileRoutesByPath, redirect } from "@tanstack/react-router";

/**
 * Canonical SPA route paths for chat surfaces.
 *
 * Thread URLs always include the `/c/` segment under agent chat
 * (`…/chat/c/$threadId`). Prefer the helpers below over inline `to:` strings —
 * NavRow and other untyped Link wrappers accept `string` and will not catch a
 * missing `/c/`.
 *
 * `satisfies keyof FileRoutesByPath` fails typecheck if a route file is renamed
 * without updating these constants.
 */
export const AGENT_CHAT_ROUTE =
	"/$owner/agents/$agentId/chat" satisfies keyof FileRoutesByPath;
export const AGENT_THREAD_ROUTE =
	"/$owner/agents/$agentId/chat/c/$threadId" satisfies keyof FileRoutesByPath;

export function agentChatLink(owner: string, agentId: string) {
	return {
		to: AGENT_CHAT_ROUTE,
		params: { owner, agentId },
	} as const;
}

export function agentThreadLink(
	owner: string,
	agentId: string,
	threadId: string,
) {
	return {
		to: AGENT_THREAD_ROUTE,
		params: { owner, agentId, threadId },
	} as const;
}

export function isAgentSkillsSubPage(
	owner: string,
	agentId: string,
	pathname: string,
): boolean {
	const base = `/${owner}/agents/${agentId}/skills/`;
	return pathname.startsWith(base);
}

export function isAgentSkillsTab(
	owner: string,
	agentId: string,
	pathname: string,
): boolean {
	const index = `/${owner}/agents/${agentId}/skills`;
	return pathname === index || pathname === `${index}/`;
}

/** Workspace Home (ops awareness) lives only at the org root. */
export function isOwnerHomePath(owner: string, pathname: string): boolean {
	const prefix = `/${owner}`;
	return pathname === prefix || pathname === `${prefix}/`;
}

export function redirectBareAgentToChat(owner: string, agentId: string): void {
	throw redirect({
		...agentChatLink(owner, agentId),
		replace: true,
	});
}
