/**
 * The "Client apps" arm of the home activity timeline: one row per MCP client
 * session (ChatGPT, Claude, the CLI), read from `/clients/sessions`. Rows link
 * to the Connected apps page under connectors, which carries inventory and
 * revoke controls.
 */
export function ClientSessionsTimeline({ owner }: { owner: string }) {
	const {
		data: sessions = [],
		isLoading,
		isError,
	} = useClientSessions({
		refetchInterval: 60_000,
	});

	if (isLoading && sessions.length === 0) {
		return (
			<div className="space-y-2">
				{Array.from({ length: 3 }).map((_, i) => (
					<div
						// biome-ignore lint/suspicious/noArrayIndexKey: static skeleton
						key={i}
						className={cn(FILLED_BOX, "h-14 animate-pulse")}
					/>
				))}
			</div>
		);
	}

	if (isError && sessions.length === 0) {
		return (
			<p className="py-6 text-center text-sm text-destructive">
				Could not load client app activity.
			</p>
		);
	}

	if (sessions.length === 0) {
		return (
			<div className="flex flex-col items-center gap-2 py-8 text-center">
				<AppWindow className="h-5 w-5 text-muted-foreground" />
				<p className="text-sm text-muted-foreground">
					No client app activity yet. Connect ChatGPT, Claude, or the CLI over
					MCP and its sessions show up here.
				</p>
			</div>
		);
	}

	return (
		<div className="flex flex-col gap-1">
			{sessions.map((session) => {
				const toolSummary = session.tools.slice(0, 3).join(", ");
				return (
					<Link
						key={session.sessionId}
						to="/$owner/connectors"
						params={{ owner }}
						search={{}}
						className="flex w-full items-start gap-3 rounded-lg p-3 text-left transition-colors hover:bg-accent/50"
					>
						<AppWindow className="mt-0.5 h-4 w-4 shrink-0 text-muted-foreground" />
						<div className="min-w-0 flex-1">
							<div className="flex items-baseline gap-2">
								<span className="truncate text-sm font-medium">
									{session.clientName?.trim() || "MCP client"}
								</span>
								<span className="shrink-0 text-xs text-muted-foreground">
									{formatTimeAgo(session.lastCallAt)}
								</span>
							</div>
							<div className="truncate text-xs text-muted-foreground">
								{session.callCount} {session.callCount === 1 ? "call" : "calls"}
								{session.failedCount > 0
									? ` · ${session.failedCount} failed`
									: ""}
								{toolSummary ? ` · ${toolSummary}` : ""}
							</div>
						</div>
						{session.pendingInteractionCount > 0 ? (
							<span className="shrink-0 rounded-md bg-amber-500/15 px-1.5 py-0.5 text-[10px] font-medium text-amber-600 dark:text-amber-400">
								{session.pendingInteractionCount} pending
							</span>
						) : null}
					</Link>
				);
			})}
		</div>
	);
}
