/**
 * Scope resolution: `tryResolveApiScopeSlug` (render-safe) vs `resolveApiScope`
 * (strict, for request URLs).
 *
 * Pins the regression where building a query key from `resolveApiScope` during
 * render crashed <AppSidebar> at the bare root path (no org scope yet) — the
 * strict resolver throws there; the render-safe one must return null instead.
 *
 * Runs in the `node` vitest project (no `window`), so `getPathScope()` yields a
 * null path slug — exactly the "no scope resolvable yet" case.
 */

import { afterEach, describe, expect, it, vi } from 'vitest';
import {
  ApiError,
  apiCall,
  apiErrorFor,
  isNotFoundError,
  isServerError,
  resolveApiScope,
  throwIfNotOk,
  tryResolveApiScopeSlug,
} from './core';

afterEach(() => {
  vi.restoreAllMocks();
});

describe('tryResolveApiScopeSlug (render-safe)', () => {
  it('returns a string orgContext as the slug', () => {
    expect(tryResolveApiScopeSlug('buremba')).toBe('buremba');
  });

  it('prefers orgContext.slug', () => {
    expect(tryResolveApiScopeSlug({ slug: 'buremba', organizationId: 'org_123' })).toBe('buremba');
  });

  it('returns null (does NOT throw) when only an org id is known and no URL scope', () => {
    // The render-crash regression: an orgContext with no slug, at the root
    // path. Must be null, not an exception.
    expect(() => tryResolveApiScopeSlug({ organizationId: 'org_123' })).not.toThrow();
    expect(tryResolveApiScopeSlug({ organizationId: 'org_123' })).toBeNull();
  });

  it('returns null for an empty/undefined orgContext with no URL scope', () => {
    expect(tryResolveApiScopeSlug(undefined)).toBeNull();
    expect(tryResolveApiScopeSlug('')).toBeNull();
  });
});

describe('resolveApiScope (strict)', () => {
  it('resolves a slug when one is available', () => {
    expect(resolveApiScope('buremba')).toEqual({ slug: 'buremba' });
    expect(resolveApiScope({ slug: 'buremba' })).toEqual({ slug: 'buremba' });
  });

  it('still throws when no slug is resolvable (request URLs require one)', () => {
    expect(() => resolveApiScope({ organizationId: 'org_123' })).toThrow(
      /Organization slug is required/,
    );
    expect(() => resolveApiScope(undefined)).toThrow();
  });
});

describe('API error status', () => {
  function jsonResponse(status: number, body: unknown): Response {
    return new Response(JSON.stringify(body), {
      status,
      headers: { 'Content-Type': 'application/json' },
    });
  }

  it('carries the HTTP status on the thrown error', async () => {
    const notFound = jsonResponse(404, {
      error: 'invalid_request',
      error_description: "Organization 'nope' not found",
    });

    await expect(
      throwIfNotOk(notFound, 'Failed to resolve path'),
    ).rejects.toSatisfy((error: unknown) => isNotFoundError(error));
  });

  it('carries the HTTP status through apiCall', async () => {
    vi.spyOn(globalThis, 'fetch').mockResolvedValueOnce(
      jsonResponse(404, {
        error: 'invalid_request',
        error_description: "Organization 'nope' not found",
      }),
    );

    await expect(
      apiCall('resolve_path', { path: '/nope' }, { slug: 'nope' }),
    ).rejects.toMatchObject({
      name: 'ApiError',
      status: 404,
    });
  });

  it('preserves an error_description from REST responses', async () => {
    const error = await apiErrorFor(
      jsonResponse(404, {
        error: 'invalid_request',
        error_description: "Organization 'nope' not found",
      }),
    );

    expect(error).toBeInstanceOf(ApiError);
    expect(error.message).toBe("Organization 'nope' not found");
    expect(error.status).toBe(404);
  });

  it('does not treat a server failure as not-found', async () => {
    const serverError = jsonResponse(500, { message: 'boom' });

    await expect(
      throwIfNotOk(serverError, 'Failed to resolve path'),
    ).rejects.toSatisfy((error: unknown) => !isNotFoundError(error));
  });

  it('still surfaces the server-provided message', async () => {
    const notFound = jsonResponse(404, { message: 'Organization not found' });

    await expect(throwIfNotOk(notFound, 'fallback')).rejects.toThrow(
      'Organization not found',
    );
  });
});

describe('isServerError', () => {
  it('is true for a 5xx', () => {
    expect(isServerError(new ApiError('boom', 500))).toBe(true);
    expect(isServerError(new ApiError('gateway', 502))).toBe(true);
  });

  it('is false for a refusal the UI has its own path for', () => {
    // 401 sends you to sign in and 403 asks for access; calling either an
    // outage strands the visitor on an error page instead.
    expect(isServerError(new ApiError('Unauthorized', 401))).toBe(false);
    expect(isServerError(new ApiError('Forbidden', 403))).toBe(false);
    expect(isServerError(new ApiError('not found', 404))).toBe(false);
