 *
 * Letting clientInfo win made two things wrong at once, both measured on prod
 * 2026-07-30 (19 rows, all 19 mismatched):
 *   - the displayed vendor was the driver, not the app: "Owletto for Mac" and
 *     "Lobu CLI" both rendered as "claude-code", ChatGPT as "openai-mcp"
 *   - `firstParty` keyed off that polluted name, so Lobu's own surfaces lost
 *     their badge whenever a third-party runtime drove them — that field is
 *     now deleted rather than repaired (see the third test)
 *
 * Both fixtures below are copied from real prod rows.
 */

import { beforeAll, beforeEach, describe, expect, test } from 'bun:test';
import {
  ensureDbForGatewayTests,
  resetTestDatabase,
} from '../../gateway/__tests__/helpers/db-setup.js';
import { authStash, installRouteTestMocks } from './helpers/route-test-mocks';

installRouteTestMocks();

const ORG = 'org-identity';
const USER = 'u-owner';

/** Prod row: registered "Owletto for Mac", driven by the Claude Code SDK. */
const MAC_CLIENT = 'mcp_client_owletto_mac';
/** Prod row: registered "ChatGPT", reports itself as "openai-mcp". */
const CHATGPT_CLIENT = 'mcp_client_chatgpt';

beforeAll(async () => {
  await ensureDbForGatewayTests();
}, 60_000);

async function importClientRoutes() {
  const mod = await import('../client-routes.js');
  return mod.clientRoutes;
}

async function seed(): Promise<void> {
  const { getDb } = await import('../../db/client.js');
  const sql = getDb();

  await sql`
    INSERT INTO "user" (id, name, email, "emailVerified", "createdAt", "updatedAt")
    VALUES (${USER}, 'Owner', 'owner@test', true, now(), now())
    ON CONFLICT (id) DO NOTHING
  `;
  await sql`
    INSERT INTO organization (id, name, slug)
    VALUES (${ORG}, ${ORG}, ${ORG})
    ON CONFLICT (id) DO NOTHING
  `;

  // Registered as "Owletto for Mac" but every session reports `claude-code`,
  // because the Mac app drives its MCP connection through the Claude Code SDK.
  await sql`
    INSERT INTO oauth_clients (id, client_name, software_id, software_version, redirect_uris, metadata)
    VALUES (
      ${MAC_CLIENT}, 'Owletto for Mac', 'owletto-mac', '0.1.0',
      ARRAY['http://127.0.0.1:59123/callback']::text[],
      ${sql.json({
        last_client_info: { name: 'claude-code', version: '2.1.198' },
        last_user_agent: 'claude-code/2.1.198 (sdk-cli)',
      })}
    )
    ON CONFLICT (id) DO NOTHING
  `;
  await sql`
    INSERT INTO oauth_clients (id, client_name, redirect_uris, metadata)
    VALUES (
      ${CHATGPT_CLIENT}, 'ChatGPT',
      ARRAY['https://chatgpt.com/connector/oauth/vZ8jgAUNyIH4']::text[],
      ${sql.json({
        last_client_info: { name: 'openai-mcp', version: '1.0.0' },
        last_user_agent: 'openai-mcp/1.0.0',
      })}
    )
    ON CONFLICT (id) DO NOTHING
  `;

  for (const clientId of [MAC_CLIENT, CHATGPT_CLIENT]) {
    await sql`
      INSERT INTO oauth_tokens (
        id, token_type, token_hash, client_id, user_id, organization_id,
        scope, expires_at, created_at
      ) VALUES (
        ${`tok_${clientId}`}, 'access', ${`hash_${clientId}`}, ${clientId}, ${USER}, ${ORG},
        'mcp:read', now() + interval '1 hour', now()
      )
      ON CONFLICT (id) DO NOTHING
    `;
  }
}

interface ListedClient {
  id: string;
  title: string | null;
  drivenBy: string | null;
}

async function listClients(): Promise<Map<string, ListedClient>> {
  const routes = await importClientRoutes();
  const res = await routes.request('/');
  expect(res.status).toBe(200);
  const body = (await res.json()) as { clients: ListedClient[] };
  return new Map(body.clients.map((c) => [c.id, c]));
}

describe('MCP client identity', () => {
  beforeEach(async () => {
    await resetTestDatabase();
    await seed();
    authStash.organizationId = ORG;
    authStash.memberRole = 'owner';
  });

  test('the listed title is the registered name, not the driving process', async () => {
    const clients = await listClients();

    // Before the fix both of these returned the clientInfo name, so the UI
    // showed "claude-code" for a Lobu product and "openai-mcp" for ChatGPT.
    expect(clients.get(MAC_CLIENT)?.title).toBe('Owletto for Mac');
    expect(clients.get(CHATGPT_CLIENT)?.title).toBe('ChatGPT');
  });

  test('the driving process is still reported, on its own field', async () => {
    // clientInfo answers a genuinely useful but DIFFERENT question — what is
    // driving the connection. Keeping it costs nothing once it stops
    // overriding identity.
    const clients = await listClients();

    expect(clients.get(MAC_CLIENT)?.drivenBy).toBe('claude-code');
    expect(clients.get(CHATGPT_CLIENT)?.drivenBy).toBe('openai-mcp');
  });

  test('no client is classified as first-party by its self-asserted name', async () => {
    // `firstParty` used to be derived from a hardcoded software-id allowlist
    // plus a "lobu*" name-prefix match. The allowlist went stale at the
    // Lobu→Owletto rename (that staleness was half this bug), and the prefix
    // fallback let any registration claim the category by naming itself.
    // Both signals are supplied by the client at registration, so neither can
    // classify anything. Its only consumers were two cosmetic labels; the
    // field is gone rather than re-derived.
    const clients = await listClients();

    for (const client of clients.values()) {
      expect(client).not.toHaveProperty('firstParty');
    }
  });
});

import path from 'node:path';
import type { ProxyOptions } from 'vite';
import { TanStackRouterVite } from '@tanstack/router-plugin/vite';
import react from '@vitejs/plugin-react';
import { defineConfig } from 'vite';

/**
 * Optional same-origin reverse-proxy to a remote Lobu API (usually prod).
 *
 * Setting `VITE_API_URL=https://app.lobu.ai` does *not* work for interactive
 * login: session cookies are Host/Domain-scoped to the API origin (and often
 * `Secure` + `AUTH_COOKIE_DOMAIN=.lobu.ai`), so the SPA on localhost never
 * receives them. Point the SPA at itself (no VITE_API_URL) and proxy `/api`
 * instead — cookies land on localhost and subsequent fetches stay same-origin.
 *
 *   LOBU_API_PROXY=https://app.lobu.ai bun run dev -- --host localhost --port 5173
 *
 * Full-page gateway navigations (App install `/lobu/.../install`) do **not**
 * go through this proxy: `appInstallUrl` uses `VITE_GATEWAY_URL` (injected from
 * `LOBU_API_PROXY` below) so OAuth starts on the real gateway whose
 * `redirect_uri` is registered with the provider.
 *
 * Auth options on the SPA origin:
 *   - `?lobu_token=<PAT>` handoff (from `lobu login` against the cloud context)
 *   - login through the `/api` proxy when better-auth allows it
 */
function prodApiProxy(): Record<string, ProxyOptions> | undefined {
  const target = process.env.LOBU_API_PROXY?.trim();
  if (!target) return undefined;

  const rewriteCookies: NonNullable<ProxyOptions['configure']> = (proxy) => {
    proxy.on('proxyRes', (proxyRes) => {
      const raw = proxyRes.headers['set-cookie'];
      if (!raw) return;
      const list = Array.isArray(raw) ? raw : [raw];
      // Prod cookies often carry Domain=.lobu.ai (or similar). Drop Domain so
      // the cookie becomes host-only for the SPA origin (localhost). Keep the
      // Secure flag: Better Auth names the session `__Secure-…`, which browsers
      // reject unless Secure is set (http://localhost is a secure context).
      proxyRes.headers['set-cookie'] = list.map((cookie) =>
        cookie
          .replace(/;\s*Domain=[^;]*/gi, '')
          .replace(/;\s*SameSite=None/gi, '; SameSite=Lax'),
      );
    });
  };

  const shared: ProxyOptions = {
    target,
    changeOrigin: true,
    secure: true,
    ws: true,
    configure: rewriteCookies,
  };

  return {
    // XHR/fetch + cookies stay same-origin on the SPA host.
    '/api': shared,
    '/oauth': shared,
    '/connect': shared,
  };
}

const lobuApiProxy = process.env.LOBU_API_PROXY?.trim() || '';

export default defineConfig({
  appType: 'spa',
  // src/main.tsx uses a top-level `await` to halt SPA boot during the
  // PAT-in-URL handoff redirect. Vite's default target (es2020 + safari14)
  // doesn't allow top-level await, so prod builds fail in esbuild's
  // transpile step. Bump to esnext — every browser we ship to (Chromium ≥89,
  // Safari ≥15, Firefox ≥90) supports top-level await natively.
  build: {
    target: 'esnext',
    // Workspace packages resolve to their real paths outside node_modules.
    // Include their compiled output so Rollup transforms CommonJS exports
    // before those modules reach a browser chunk.
    commonjsOptions: {
      include: [/node_modules/, /packages[\\/][^\\/]+[\\/]dist/],
    },
  },
  // Split SPA → remote gateway: bake the gateway origin so App install links
  // leave the Vite host and hit the host that owns OAuth redirect_uris.
  // Empty string in co-hosted prod / `make dev` → appInstallUrl stays relative.
  define: {
    'import.meta.env.VITE_GATEWAY_URL': JSON.stringify(lobuApiProxy),
  },
  plugins: [
    TanStackRouterVite({
      routesDirectory: './src/app',
      generatedRouteTree: './src/routeTree.gen.ts',
      // Split each route's component into its own lazy chunk so the initial
      // bundle only carries the router shell + the landed route, not all 37
      // route trees. One flag instead of hand-maintaining .lazy.tsx files.
      autoCodeSplitting: true,
    }),
    react(),
  ],
  resolve: {
    alias: {
      '@': path.resolve(__dirname, './src'),
      // @lobu/core ships CJS dist (`module: CommonJS`). Vite dev would otherwise
      // serve dist/*.js raw over ESM (`exports is not defined`). Point the
      // browser at source — same as the package's `"bun"` export condition.
      // ONLY browser-safe subpaths (errors, reserved). Never alias the package
      // root: the barrel re-exports logger/otel/sentry and would crash the SPA
      // with `process is not defined`.
      '@lobu/core/errors': path.resolve(__dirname, '../core/src/errors.ts'),
      '@lobu/core/reserved': path.resolve(__dirname, '../core/src/reserved.ts'),
    },
  },
  optimizeDeps: {
    // If anything else hits @lobu/core CJS dist, force prebundle interop.
    include: ['@lobu/core/errors', '@lobu/core/reserved', '@shadcn/react/message-scroller'],
  },
  server: {
    // Prefer `localhost` over 127.0.0.1 when using LOBU_API_PROXY so Secure-cookie
    // quirks and better-auth trustedOrigins line up with the common dev host.
    allowedHosts: true,
    proxy: prodApiProxy(),
    hmr: process.env.VITE_HMR_HOST
      ? {
          host: process.env.VITE_HMR_HOST,
          clientPort: Number(process.env.VITE_HMR_CLIENT_PORT || 8443),
          protocol: process.env.VITE_HMR_PROTOCOL || 'wss',
        }
      : undefined,
  },
});
