export function AppSidebar({
	embedded = false,
	collapsed = false,
	onToggleCollapsed,
}: {
	embedded?: boolean;
	collapsed?: boolean;
	onToggleCollapsed?: () => void;
}) {
	const {
		agentId = null,
		threadId = null,
		conversationId = null,
		watcherId = null,
		clientId = null,
	} = useParams({
		strict: false,
	}) as {
		agentId?: string;
		threadId?: string;
		conversationId?: string;
		watcherId?: string;
		clientId?: string;
	};
	const { pathname, search } = useLocation();
	const searchRecord = (search ?? {}) as Record<string, unknown>;
	const { currentOwner } = useOrgContext();
	const owner =
		currentOwner && !currentOwner.startsWith("@") ? currentOwner : null;
	// The Builder (system agent) is shown FIRST in the Agents roster (via
	// rosterAgents). Click an agent → chat; expand for configuration destinations.
	const { rosterAgents, systemAgentId, isLoading } = useWorkingAgents();
	const rosterAgentIds = useMemo(
		() => rosterAgents.map((agent) => agent.agentId),
		[rosterAgents],
	);
	const { threads: recentThreads } = useRecentAgentThreads(
		owner,
		rosterAgentIds,
		{ enabled: !!owner && rosterAgentIds.length > 0, limit: RECENT_LIMIT },
	);
	const { data: connectedClients = [] } = useConnectedClients(null, {
		enabled: !!owner,
	});
	const mcpClients = useMemo(
		() => groupClients(connectedClients).filter((client) => client.connected),
		[connectedClients],
	);

	// MCP activity is write-time materialized as each registered client's
	// `lastSeenAt`. `groupClients` collapses re-registrations of the same app,
	// and expired/revoked grants stay out of Recent. Every live source is sorted
	// together before applying the visible limit.
	const recentItems = useMemo(() => {
		return [
			...recentThreads.map((thread) => ({
				kind: "conversation" as const,
				at: thread.updatedAt,
				thread,
			})),
			...mcpClients.map((client) => ({
				kind: "mcp" as const,
				at: client.lastSeenAt ?? 0,
				client,
			})),
		]
			.sort((a, b) => b.at - a.at)
			.slice(0, RECENT_LIMIT);
	}, [mcpClients, recentThreads]);

	// "New agent" links straight to the builder chat with a prompt (see helpers
	// — the /$owner redirect would drop search params).
	const newAgent = newAgentLink({ owner, systemAgentId });
	// Collapsed icon-rail — only on the wide fixed sidebar (never embedded in the
	// narrow drawer, which is already a compact off-canvas panel).
	const isRail = collapsed && !embedded;

	if (isRail) {
							rosterAgents.map((agent) => (
								<AgentRow
									key={agent.agentId}
									ownerSlug={owner}
									agentId={agent.agentId}
									name={agent.name}
									status={agent.status}
									selected={agentId === agent.agentId}
								/>
							))
						)}

						{recentItems.length > 0 ? (
							<>
								<SectionHeader label="Recent" />
								{recentItems.map((item) => {
									if (item.kind === "mcp") {
										return (
											<NavRow
												key={`mcp:${item.client.key}`}
												to="/$owner/connectors/client/$clientId"
												params={{
													owner,
													clientId: item.client.clientId,
												}}
												active={
													clientId != null &&
													item.client.clientIds.includes(clientId)
												}
												icon={AppWindow}
												label={item.client.title}
											/>
										);
									}

									const conv = item.thread;
									const isWeb = (conv.platform ?? "web") === "web";
									if (conv.platform === "behavior" && conv.behaviorId != null) {
										return (
											<NavRow
												key={`behavior:${conv.agentId}:${conv.behaviorId}`}
												to="/$owner/agents/$agentId/behaviors/$watcherId"
												params={{
													owner,
													agentId: conv.agentId,
													watcherId: String(conv.behaviorId),
												}}
												active={
													agentId === conv.agentId &&
													watcherId === String(conv.behaviorId)
												}
												icon={platformIcon(conv.platform)}
												label={conv.title}
											/>
										);
									}
									if (!isWeb) {
										return (
											<NavRow
												key={`conversation:${conv.agentId}:${conv.id}`}
												to="/$owner/agents/$agentId/conversations/$conversationId"
												params={{
													owner,
													agentId: conv.agentId,
													conversationId: conv.conversationId ?? conv.id,
												}}
												active={
													agentId === conv.agentId &&
													conversationId === (conv.conversationId ?? conv.id)
												}
												icon={platformIcon(conv.platform)}
												label={conv.title}
											/>
										);
									}

									const threadLink = agentThreadLink(
										owner,
										conv.agentId,
										conv.id,
									);
									return (
										<NavRow
											key={`chat:${conv.agentId}:${conv.id}`}
											to={threadLink.to}
											params={threadLink.params}
											active={agentId === conv.agentId && threadId === conv.id}
											icon={MessageSquare}
											label={conv.title}
										/>
									);
								})}
							</>
						) : null}
					</div>

					<UserMenu />
				</>
			) : (
				<div className="flex flex-1 flex-col items-center justify-center px-4 text-center text-xs text-sidebar-foreground/50">
					Pick an organization to continue.

