import type {
	AgentInlineGuardrail as AgentInlineGuardrailCore,
	AgentSettings as AgentSettingsCore,
	SkillConfig,
	SuggestedPrompt,
} from "@lobu/core";
import { useMutation, useQueries, useQuery } from "@tanstack/react-query";
import { toast } from "sonner";
import { API_URL, fetchWithTimeout, getPathScope, throwIfNotOk } from "./core";
import { createMutation, createRestMutation } from "./hook-factory";

// ============================================================
// Types
// ============================================================

export interface AgentItem {
	agentId: string;
	name: string;
	description?: string;
	owner: { platform: string; userId: string };
	createdAt: number;
	lastUsedAt?: number;
	connectionCount: number;
	activeConnectionCount: number;
	clientCount: number;
	watcherCount: number;
	userCount: number;
	platforms: string[];
	providers: string[];
	status: "active" | "idle";
}

export type AgentAuthType = "oauth" | "device-code" | "api-key";

export interface AgentAuthProfile {
	id: string;
	provider: string;
	model: string;
	/** Only sent on writes; the API never returns a resolved credential. */
	credential?: string;
	label: string;
	authType: AgentAuthType;
	metadata?: {
		email?: string;
		expiresAt?: number;
		refreshToken?: string;
		accountId?: string;
	};
	createdAt: number;
}

/** Start response, discriminated by `mode`. authorization-code (Claude) returns
 *  a redirect URL to open; device-code (ChatGPT) returns a user code to show. */
export type AgentProviderOAuthStartResponse =
	| { mode: "redirect"; authorizeUrl: string }
	| {
			mode: "device";
			userCode: string;
			deviceAuthId: string;
			interval: number;
			verificationUrl: string;
	  };

/** Complete response. Device polls return `pending` until the user authorizes. */
export interface AgentProviderOAuthCompleteResponse {
	status: "pending" | "success";
	error?: string;
}

// AgentSkillConfig is the canonical SkillConfig from @lobu/core (the TypeBox
// schema's Static<> in contracts/agent-settings.ts). Re-exported under the
// local name so existing imports keep resolving. The schema is a superset of
// the hand-written shape that used to live here (it also carries
// modelPreference/thinkingLevel); all fields owletto reads are
// present, so this is a safe widening.
export type AgentSkillConfig = SkillConfig;

export interface AgentSkillsCatalogItem {
	skillId: string;
	repo: string;
	name: string;
	description?: string;
	instructions?: string;
	hidden: boolean;
	installed: boolean;
}

interface AgentSkillsCatalogResponse {
	catalog: AgentSkillsCatalogItem[];
	installedSkills: AgentSkillConfig[];
}

// AgentSettings is the canonical shape from @lobu/core (derived from
// AgentSettingsStoredSchema via Static<>). Re-exported under the local name so
// existing imports keep resolving. The hand-written copy that lived here had
// drifted: `models` was required (server treats undefined as allow-all),
// `sandboxId` was `string | null` (store collapses both to null), it carried
// a dead `mcpServers` field (zero references), and it was missing
// `preApprovedTools`. Importing the contract kills the duplicate so the two
// can never drift again.
//
// `authProfiles` is layered on here (separate-store: Postgres keeps it
// elsewhere, GET merges dynamically) — matches the core AgentSettings shape.
export type AgentSettings = AgentSettingsCore;

// GuardrailStage is the canonical union from @lobu/core (exported via the
// guardrails module). Imported for local use AND re-exported under the local
// barrel so the ~5 UI files importing it from '@/lib/api' resolve to one
// definition. Core's GuardrailStageSchema is _StageCheck-guarded against
// this same union.
import type { GuardrailStage } from "@lobu/core";

export type { GuardrailStage };

// AgentInlineGuardrail is the canonical shape from @lobu/core (the schema's
// Static<>). Re-exported under the local name so existing imports resolve.
export type AgentInlineGuardrail = AgentInlineGuardrailCore;

export interface GuardrailCatalogItem {
	/** Stable identifier — matches the name registered in `GuardrailRegistry`. */
	name: string;
	/**
	 * Every stage this guardrail is registered at. A name is the unit of
	 * configuration (enabling it arms all of its stages), so a single catalog
	 * item can span more than one stage — e.g. `pii-scan` runs at input,
	 * output, and pre-tool.
	 */
	stages: GuardrailStage[];
	description?: string;
}

export interface GuardrailTripEvent {
	id: number;
	occurredAt: string;
	agentId: string;
	agentName?: string;
	stage: GuardrailStage;
	guardrailName: string;
	reason?: string;
	/** Conversation the trip fired in, when known (egress trips carry it). */
	conversationId?: string;
}

interface AgentDetail extends AgentItem {
	settings: AgentSettings;
}

// ============================================================
// URL helpers
// ============================================================

export function agentsUrl(orgSlug: string, path = "") {
	return `${API_URL}/api/${orgSlug}/agents${path}`;
}

function agentHistoryUrl(agentId: string, path = "") {
	return `${API_URL}/lobu/api/v1/agents/${agentId}/history${path}`;
}

export interface AgentThreadItem {
	id: string;
	title: string;
	createdAt: number;
	updatedAt: number;
	/** "web" for app threads; "behavior" for behavior activity; otherwise the
	 *  source platform (slack, telegram…). */
	platform?: string;
	/** Raw conversation id — used to open a platform conversation read-only. */
	conversationId?: string;
	/** Set on behavior entries — routes to the behavior's page. */
	behaviorId?: number;
}

export interface AgentThreadMessage {
	id: string;
	type: string;
	role?: string;
	content: unknown;
	timestamp: string;
	isVerbose?: boolean;
}

/** Durable interaction cards replayed on history load. The transcript doesn't
 * carry these parts, so the server derives approvals from events and the latest
 * terminal agent error from the Postgres-backed response queue. */
export interface ToolApprovalThreadInteraction {
	type: "tool-approval";
	eventId: number;
	runId: number;
	action: string | null;
	proposal: Record<string, unknown> | null;
	current: Record<string, unknown> | null;
	/** entity_field_change proposal: field_path -> proposed value. Present when
	 *  the approval is an agent/watcher entity-field write blocked by human
	 *  ownership (distinct from the manage_agents name/description proposal). */
	fields?: Record<string, unknown> | null;
	/** entity_field_change attribution: 'agent' | 'behavior'. */
	attribution?: "agent" | "behavior" | null;
	/** Discriminator: "agent" | "behavior" | "entity". */
	resourceKind?: "agent" | "behavior" | "entity" | null;
	/** Durable server explanation for why this proposal requires review. */
	reason?: string | null;
	/** Durable approval lifecycle state. Omitted by legacy history endpoints. */
	status?: string;
	reviewedByName?: string | null;
	windowId?: number | null;
}

export interface AgentErrorThreadInteraction {
	type: "agent-error";
	runId: number;
	error: string;
	errorCode: string | null;
	errorContext: { provider?: string; model?: string } | null;
}

/** Replayed suggested-action chips: the same `{title, message}` prompts the live
 *  `complete` SSE event carries, so a reload restores the chips shown after the
 *  latest assistant turn. Surfaced as the store's `currentSuggestions` (not a
 *  chat part). */
export interface SuggestionThreadInteraction {
	type: "suggestion";
	prompts: SuggestedPrompt[];
}

export type ThreadInteraction =
	| ToolApprovalThreadInteraction
	| AgentErrorThreadInteraction
	| SuggestionThreadInteraction;

export interface ThreadHistory {
	messages: AgentThreadMessage[];
	interactions: ThreadInteraction[];
}

function orgScopedHeaders(orgSlug?: string | null): HeadersInit | undefined {
	return orgSlug ? { "x-lobu-org": orgSlug } : undefined;
}

async function fetchAgentThreads(
	agentId: string,
	orgSlug: string | null | undefined,
	options?: { strict?: boolean; scope?: "all" },
): Promise<AgentThreadItem[]> {
	const path = options?.scope === "all" ? "/threads?scope=all" : "/threads";
	const res = await fetchWithTimeout(agentHistoryUrl(agentId, path), {
		credentials: "include",
		headers: orgScopedHeaders(orgSlug),
	});
	if (res.status === 401 || res.status === 403) return [];
	if (!res.ok) {
		if (options?.strict) {
			await throwIfNotOk(res, "Failed to fetch agent threads");
		}
		return [];
	}
	const data = (await res.json()) as { threads?: AgentThreadItem[] };
	return Array.isArray(data.threads) ? data.threads : [];
}

import {
	Link,
	useLocation,
	useNavigate,
	useParams,
} from "@tanstack/react-router";
import {
	AppWindow,
