} from "@/lib/owner-sections";
import { cn } from "@/lib/utils";
import { OrganizationDropdown } from "./organization-dropdown";

type IconComponent = ComponentType<{ className?: string }>;

function openCommandPalette() {
	document.dispatchEvent(
		new KeyboardEvent("keydown", { key: "k", metaKey: true, bubbles: true }),
	);
}

/** Visible cap of the Recent section; also caps the merged thread fetch —
 *  threads past the visible cap could never render. */
const RECENT_LIMIT = 12;

/** Icon for a conversation's source platform / system. */
function platformIcon(platform: string | undefined): IconComponent {
	switch (platform) {
		case "slack":
			return Slack;
		case "telegram":
			return Send;
		case "whatsapp":
		case "discord":
			return MessageCircle;
		case "behavior":
			return Eye;
		default:
			return MessageSquare;
	}
}

/** The Lobu pixel-claw mark (from favicon.svg). Inherits color via currentColor. */
function LobuMark({ className }: { className?: string }) {
	return (
		<svg
			viewBox="0 0 140 140"
			className={className}
			fill="currentColor"
			shapeRendering="crispEdges"
			role="img"
			aria-label="Lobu"
		>
			{/* left half */}
			<rect x="40" y="0" width="20" height="20" />
			<rect x="20" y="20" width="20" height="20" />
			<rect x="40" y="20" width="20" height="20" />
			<rect x="0" y="40" width="20" height="20" />
			<rect x="20" y="40" width="20" height="20" />
			<rect x="0" y="60" width="20" height="20" />
			<rect x="0" y="80" width="20" height="20" />
			<rect x="20" y="80" width="20" height="20" />
			<rect x="20" y="100" width="20" height="20" />
			<rect x="40" y="100" width="20" height="20" />
			<rect x="40" y="120" width="20" height="20" />
			{/* right half */}
			<rect x="80" y="0" width="20" height="20" />
			<rect x="80" y="20" width="20" height="20" />
			<rect x="100" y="20" width="20" height="20" />
			<rect x="100" y="40" width="20" height="20" />
			<rect x="120" y="40" width="20" height="20" />
			<rect x="120" y="60" width="20" height="20" />
			<rect x="100" y="80" width="20" height="20" />
			<rect x="120" y="80" width="20" height="20" />
			<rect x="80" y="100" width="20" height="20" />
			<rect x="100" y="100" width="20" height="20" />
			<rect x="80" y="120" width="20" height="20" />
		</svg>
	);
}

function SectionHeader({
	label,
	icon,
	action,
}: {
	label: string;
	/** Optional leading glyph (e.g. the Lobu mark before "Agents"). */
	icon?: ReactNode;
	/** Optional trailing action; revealed on hover of the header row. */
	action?: ReactNode;
}) {
	return (
		<div className="group/section flex items-center justify-between px-3 pb-1 pt-3">
			<span className="flex items-center gap-1.5 text-[11px] font-semibold uppercase tracking-wider text-sidebar-foreground/40">
				{icon}
				{label}
			</span>
			{action ? (
				<span className="opacity-0 transition-opacity group-hover/section:opacity-100 focus-within:opacity-100">
					{action}
				</span>
			) : null}
		</div>
	);
}

function NavRow({
	to,
	params,
	search,
	active,
	icon: Icon,
	leading,
	label,
	trailing,
}: {
	to: string;
	params?: Record<string, string>;
	search?: Record<string, unknown>;
	active: boolean;
	icon?: IconComponent;
	/** Custom leading glyph (e.g. EntityIcon). Wins over `icon` when set. */
	leading?: ReactNode;
	label: string;
	/** Right-aligned adornment (e.g. a record count). */
	trailing?: ReactNode;
}) {
	return (
		<Link
			to={to as "/"}
			params={params as never}
			search={search as never}
			className={cn(
				// Same pl-3 + fixed icon slot for every row so entity-type glyphs
				// line up with Activity / Connect / Memory above.
				"mx-2 flex items-center gap-2 rounded-md py-1.5 pl-3 pr-3 text-sm transition-colors",
				active
					? "bg-sidebar-accent text-sidebar-accent-foreground"
					: "text-sidebar-foreground/80 hover:bg-sidebar-accent/60 hover:text-sidebar-foreground",
			)}
		>
			<span className="flex h-3.5 w-3.5 shrink-0 items-center justify-center text-sidebar-foreground/60">
				{leading ?? (Icon ? <Icon className="h-3.5 w-3.5" /> : null)}
			</span>
			<span className="min-w-0 flex-1 truncate">{label}</span>
			{trailing}
		</Link>
	);
}

/**
 * Collapse override for a route-driven collapsible: the route decides the
 * default (active ⇒ open), a manual toggle wins until the route context
 * changes again. Implemented with the render-time state-reset idiom so a
 * navigation into/out of the group re-applies the route default.
 */
function useRouteDefaultOpen(routeActive: boolean): {
	open: boolean;
	setOpen: (open: boolean) => void;
} {
	const [override, setOverride] = useState<boolean | null>(null);
	const [lastRouteActive, setLastRouteActive] = useState(routeActive);
	if (routeActive !== lastRouteActive) {
		setLastRouteActive(routeActive);
		setOverride(null);
	}
	return { open: override ?? routeActive, setOpen: setOverride };
}

/** Chevron glyph for a collapsible nav group (label the wrapping button). */
function GroupChevron({ open }: { open: boolean }) {
	return (
		<span className="flex h-5 w-5 shrink-0 items-center justify-center rounded-md text-sidebar-foreground/40 transition-colors hover:bg-sidebar-accent/60 hover:text-sidebar-foreground">
			<ChevronRight
				className={cn(
					"h-3.5 w-3.5 transition-transform",
					open ? "rotate-90" : "rotate-0",
				)}
			/>
		</span>
	);
}

/** Deterministic initials for an agent's avatar glyph. */
function agentInitial(name: string): string {
	return name.trim().charAt(0).toUpperCase() || "?";
}

/**
 * Right-aligned record count for a Memory entity-type row. Rendered even at
 * zero — an explicit 0 is the useful signal that a type exists but has nothing
 * in it, which is otherwise indistinguishable from the count still loading.
 */
function EntityCount({ count }: { count: number }) {
	return (
		<span className="shrink-0 text-[11px] tabular-nums text-sidebar-foreground/40">
			{count}
		</span>
	);
}

/**
 * Context in the roster: the row links to the entity map, the chevron expands
 * the workspace's entity types with their record counts.
 *
 * System types (`$member`, `$resource`, `$canvas`) are listed here, unlike in
 * the rail and scope bar. They are browsable records — `$member` is the
 * workspace's people — and a young workspace often has nothing else, so
 * filtering them left Context looking like a plain row with a broken chevron.
 */
function ContextGroup({
	ownerSlug,
	active,
	searchRecord,
}: {
	ownerSlug: string;
	active: boolean;
	searchRecord: Record<string, unknown>;
}) {
	const section = OWNER_SECTIONS.context;
	const { open, setOpen } = useRouteDefaultOpen(active);
	const { orgContext } = useOrgContext();
	const { data: entityTypes = [] } = useEntityTypes(orgContext);
	// Same org scoping as `useVisibleEntityTypes`, without its system-type filter.
	const visible = useMemo(
		() =>
			entityTypes.filter(
				(et) => !et.organization_slug || et.organization_slug === ownerSlug,
			),
		[entityTypes, ownerSlug],
	);
	// The scoped type currently being browsed, so its row takes the highlight
	// instead of the parent Context row. Two scope keys can name a type:
	// `type` when browsing the list, and `entity` (`<type>/<id>`) after
	// drilling into one record — the type stays highlighted for both.
	const activeTypeSlug =
		typeof searchRecord.type === "string"
			? searchRecord.type
			: typeof searchRecord.entity === "string"
				? searchRecord.entity.split("/")[0]
				: undefined;

	// The row keeps the highlight while the map itself is what is open; once a
	// child type is being browsed, the type's own row carries it instead.
	const isHighlighted = active && !(open && activeTypeSlug);

	return (
		<Collapsible open={open} onOpenChange={setOpen}>
			<div
				className={cn(
					"mx-2 flex items-center gap-2 rounded-md py-1.5 pl-3 pr-2 text-sm transition-colors",
					isHighlighted
						? "bg-sidebar-accent text-sidebar-accent-foreground"
						: "text-sidebar-foreground/80 hover:bg-sidebar-accent/60 hover:text-sidebar-foreground",
				)}
			>
				<Link
					to={section.to}
					params={{ owner: ownerSlug }}
					search={section.search as never}
					className="flex min-w-0 flex-1 items-center gap-2"
				>
					<span className="flex h-3.5 w-3.5 shrink-0 items-center justify-center text-sidebar-foreground/60">
						<section.icon className="h-3.5 w-3.5" />
					</span>
					{/* Expanded, this row is the parent of the type rows beneath it, but
					    it carried their exact weight and indent — so browsing a type,
					    which drops the highlight, left "Memory" reading as one more
					    entity type. Recede it while it has children on screen. The
					    highlight still wins: when the map itself is what is open, being
					    the current page matters more than being a parent. */}
					<span
						className={cn(
							"min-w-0 flex-1 truncate",
							open && !isHighlighted && "text-sidebar-foreground/50",
						)}
					>
						{section.label}
					</span>
				</Link>
				{/* No types yet ⇒ nothing to expand, so the chevron would be a
				    control that does nothing. The row still links to the map. */}
				{visible.length > 0 ? (
					<CollapsibleTrigger asChild>
						<button
							type="button"
							aria-label={
