 *
 * Only a successful response with `systemAgentId: null` means no builder is
 * provisioned; request failures must remain distinguishable from that state.
 */
export function systemAgentQueryOptions(slug: string) {
	return {
		queryKey: ["system-agent-id", slug] as const,
		queryFn: async (): Promise<{ systemAgentId: string | null }> => {
			const res = await fetchWithTimeout(agentsUrl(slug, "/system-agent"), {
				credentials: "include",
			});
			await throwIfNotOk(res, "Failed to load workspace builder");
			const data = (await res.json()) as { systemAgentId?: string | null };
			return { systemAgentId: data.systemAgentId ?? null };
		},
		staleTime: 60_000,
	};
}

export function useSystemAgentId(options?: { enabled?: boolean }) {
	const { slug } = getPathScope();

	return useQuery({
		...systemAgentQueryOptions(slug ?? ""),
		enabled: !!slug && (options?.enabled ?? true),
	});
}

export function useAgentThreads(
	agentId?: string | null,
	options?: { enabled?: boolean; orgSlug?: string | null },
) {
	const { slug } = getPathScope();
	const orgSlug = options?.orgSlug ?? slug;

	return useQuery({
		...agentThreadsQueryOptions(orgSlug, agentId ?? "", { strict: true }),
		enabled: !!orgSlug && !!agentId && (options?.enabled ?? true),
	});
}

/**
 * Recent activity across every agent in a workspace. `scope=all` is the
 * server's consolidated, materialized listing: app/API chats, platform
 * conversations (Slack, Telegram, and any other connector), and Behavior
 * activity all arrive through the same contract.
 */
export function useRecentAgentThreads(
	orgSlug?: string | null,
	agentIds?: string[],
	options?: { enabled?: boolean; limit?: number },
) {
	const limit = options?.limit ?? 8;
	const enabled =
		!!orgSlug && (agentIds?.length ?? 0) > 0 && (options?.enabled ?? true);

	const queries = useQueries({
		queries: (agentIds ?? []).map((agentId) => ({
			...agentThreadsQueryOptions(orgSlug, agentId, {
				strict: false,
				scope: "all",
			}),
			enabled,
		})),
	});

	const isLoading = enabled && queries.some((query) => query.isLoading);
	const threads = queries
		.flatMap((query, index) => {
			const agentId = agentIds?.[index];
			if (!agentId) return [];
			return (query.data ?? []).map((thread) => ({ agentId, ...thread }));
		})
		.sort((a, b) => b.updatedAt - a.updatedAt)
		.slice(0, limit);

	return { threads, isLoading };
}

