import type { ConnectionItem, FeedItem } from "@/lib/api/connections";
import { connectionLabel } from "@/lib/connection-label";

type ConnectionLabelSource = Pick<
	ConnectionItem,
	"id" | "display_name" | "connector_name" | "connector_key"
> &
	Partial<Pick<ConnectionItem, "auth_profile_name" | "auth_profile_slug">>;

export function resolveConnectionFilterLabel(
	connectionIds: number[],
	connections: ConnectionLabelSource[],
): string {
	if (connectionIds.length === 0) return "";
	const labels = connectionIds
		.map((id) => {
			const connection = connections.find((c) => c.id === id);
			return connection ? connectionLabel(connection) : null;
		})
		.filter((label): label is string => label != null);
	if (labels.length === 0) {
		return `Filtered by connection${connectionIds.length > 1 ? "s" : ""} #${connectionIds.join(", #")}`;
	}
	return labels.length === 1
		? `From ${labels[0]}`
		: `From ${labels.join(", ")}`;
}

export function resolveFeedFilterLabel(
	feedIds: number[],
	feeds: FeedItem[],
): string {
	if (feedIds.length === 0) return "";
	const parts = feedIds.map((feedId) => {
		const feed = feeds.find((f) => f.id === feedId);
		if (!feed) return null;
		const connectionName =
			feed.connection_name?.trim() ||
			feed.connector_name ||
			feed.connector_key ||
			`connection #${feed.connection_id}`;
		const feedName =
			feed.display_name?.trim() || feed.feed_key || `feed #${feed.id}`;
		return `${connectionName} · ${feedName}`;
	});
	const resolved = parts.filter((p): p is string => p != null);
	if (resolved.length === 0) {
		return `Filtered by feed${feedIds.length > 1 ? "s" : ""} #${feedIds.join(", #")}`;
	}
	return resolved.length === 1
		? `From ${resolved[0]}`
		: `From ${resolved.join("; ")}`;
}
