import type { ConnectionItem, FeedItem } from '@/lib/api/connections';
import {
  resolveConnectionFilterLabel,
  resolveFeedFilterLabel,
} from './event-filter-labels';

const connections = [
  {
    id: 3,
    connector_key: 'gmail',
    connector_name: 'Gmail',
    display_name: 'Gmail (work)',
  },
  {
    id: 7,
    connector_key: 'postgres',
    connector_name: 'Postgres',
    display_name: null,
    auth_profile_name: 'finance',
  },
] as ConnectionItem[];

const feeds = [
  {
    id: 4,
    connection_id: 3,
    display_name: 'Invoices',
    feed_key: 'invoices',
    connection_name: 'Gmail (work)',
  },
] as FeedItem[];

describe('event filter labels', () => {
  it('resolves a single connection display name', () => {
    expect(resolveConnectionFilterLabel([3], connections)).toBe(
      'From Gmail (work)'
    );
  });

  it('resolves multiple connection display names', () => {
    expect(resolveConnectionFilterLabel([3, 7], connections)).toBe(
      'From Gmail (work), Postgres · finance'
    );
  });

  it('falls back to ids when connections are unknown', () => {
    expect(resolveConnectionFilterLabel([99], connections)).toBe(
      'Filtered by connection #99'
    );
  });

  it('resolves feed labels with connection context', () => {
    expect(resolveFeedFilterLabel([4], feeds)).toBe(
      'From Gmail (work) · Invoices'
    );
  });
});"}

