import { Link, useNavigate } from "@tanstack/react-router";
import { ArrowRight, Pencil } from "lucide-react";
import { useCallback, useState } from "react";
import {
	AgentSubpageHeader,
	AgentTabShell as AgentWatchersShell,
} from "@/components/agents/agent-subpage-shell";
import {
	type BehaviorTriggersDraft,
	BehaviorTriggersEditor,
} from "@/components/agents/behaviors/behavior-triggers-editor";
import { ProposalReviewShell } from "@/components/agents/proposal-review-shell";
import { CreateWatcherForm } from "@/components/entity-tabs/watchers-tab/create-watcher-form";
import { Button } from "@/components/ui/button";
import { JsonDiff } from "@/components/ui/json-diff";
import { Skeleton } from "@/components/ui/skeleton";
import { WatcherRunThread } from "@/components/watchers/watcher-run-thread";
import { useCurrentOrg } from "@/hooks/use-current-org";
import { useOrgContext } from "@/hooks/use-org-context";
import {
	PROMOTED_DISPLAY_LIMIT,
	useAgentWatchersList,
	useWatcherDetail,
	useWatcherPromotedEntities,
} from "@/hooks/use-watchers";
import { useAgents, useResolvedPath } from "@/lib/api";
import { useAuthState } from "@/lib/auth-state";
import { cn, FILLED_BOX } from "@/lib/utils";
import { memoryBrowseTypeSearch } from "@/lib/memory-browse";

function useAgentWatchersContext(owner: string, agentId: string) {
	const { orgContext, hasOrgContext } = useOrgContext();
	const { data: resolvedData, isLoading: isResolvedLoading } = useResolvedPath(
		`/${owner}`,
		orgContext,
	);
	const { isAuthenticated } = useAuthState();
	const { isMember, isLoading: isOrgLoading } = useCurrentOrg();
	const canManageWorkspace = isAuthenticated && isMember;
	const { data: agents = [], isLoading: isAgentsLoading } = useAgents({
		enabled: canManageWorkspace,
	});

	const workspace = resolvedData?.workspace;
	const isLoading = canManageWorkspace
		? !hasOrgContext || isResolvedLoading || isAgentsLoading || isOrgLoading
		: isResolvedLoading || isOrgLoading;

	const agent = agents.find((a) => a.agentId === agentId) ?? null;

	return {
		organizationId: workspace?.id ?? "",
		agent,
		isLoading,
	};
}

/**
 * Activity surface product strip: one line linking to the behavior's durable
 * outputs. The old full "Recap" (merged JSON / per-entity field approve UI)
 * was removed — ownership/corrections live on the entity page; this page is
 * for automation health + runs.
 */
export function BehaviorOutputsStrip({
	owner,
	watcherId,
	organizationId,
}: {
	owner: string;
	watcherId: string;
	organizationId: string;
}) {
	const { data: promoted, isLoading } = useWatcherPromotedEntities(
		watcherId,
		organizationId,
	);
	const resultCount = promoted?.length ?? 0;
	const hasMore = resultCount > PROMOTED_DISPLAY_LIMIT;
	const count = Math.min(resultCount, PROMOTED_DISPLAY_LIMIT);
	// Label/link by the OBSERVED output types, never the current keying_config:
	// after an output-type change the historical rows span types, and a
	// config-derived label would count all of them while linking to only the
	// newest type's subset. An overflowed fetch is only a sample — it cannot
	// prove the unfetched tail shares the type, so stay generic then too.
	const promotedTypes = new Set(
		promoted?.map((entity) => entity.entity_type).filter(Boolean) ?? [],
	);
	const entityType =
		!hasMore && promotedTypes.size === 1 ? [...promotedTypes][0] : null;

	if (isLoading) {
		return <Skeleton className="h-10 w-full rounded-lg" />;
	}
	if (count === 0) return null;

	const displayCount = hasMore ? `${PROMOTED_DISPLAY_LIMIT}+` : String(count);
	const label =
		entityType != null
			? `${displayCount} ${entityType} ${count === 1 ? "entity" : "entities"} built by this behavior`
			: `${displayCount} ${count === 1 ? "entity" : "entities"} built by this behavior`;

	const memoryLink =
		entityType != null
			? memoryBrowseTypeSearch(owner, entityType)
			: {
					to: "/$owner/memory" as const,
					params: { owner },
					search: {},
				};

	return (
		<div
			className={cn(
				FILLED_BOX,
				"flex flex-wrap items-center justify-between gap-2 px-3 py-2.5 text-sm",
			)}
		>
			<span className="text-muted-foreground">{label}</span>
			<Button asChild variant="ghost" size="sm" className="h-7 gap-1">
				<Link
	return (
		<AgentWatcherDetailPane
			agentId={agentId}
			owner={owner}
			watcherId={watcherId}
			organizationId={organizationId}
		/>
	);
}

export function AgentWatcherBehaviorRoute({
	owner,
	agentId,
	watcherId,
	view,
	runId,
}: {
	owner: string;
	agentId: string;
	watcherId: string;
	view: WatcherBehaviorView;
	runId?: number;
}) {
	const navigate = useNavigate();
	const { data: watchers = [], isLoading: isWatchersLoading } =
		useAgentWatchersList(agentId);
	const watcherName =
		watchers.find((w) => String(w.behavior_id) === watcherId)?.name ??
		"Behavior";
	const backToBehaviors = () =>
		void navigate({
			to: "/$owner/agents/$agentId/behaviors",
			params: { owner, agentId },
		});
	const toActivity = () =>
		void navigate({
			to: "/$owner/agents/$agentId/behaviors/$watcherId",
			params: { owner, agentId, watcherId },
			search: { view: "activity", run_id: undefined },
		});
	// Editing = the `definition` view. A runId is a config-approval review, which
	// owns its own Approve/Reject lifecycle — no Edit toggle there.
	const isEditing = !runId && view === "definition";
	const headerAction = runId ? null : isEditing ? (
		<Button
			type="button"
			variant="ghost"
			size="sm"
			className="h-8 text-muted-foreground hover:text-foreground"
			onClick={toActivity}
		>
			Done
		</Button>
	) : (
		<Button asChild variant="ghost" size="sm" className="h-8 gap-1.5">
			<Link
				to="/$owner/agents/$agentId/behaviors/$watcherId"
				params={{ owner, agentId, watcherId }}
				search={{ view: "definition", run_id: undefined }}
			>
				<Pencil className="h-3.5 w-3.5" />
				Edit
			</Link>
		</Button>
	);
	return (
		<AgentWatchersShell>
			<AgentSubpageHeader
