import type { EntityPathSegment } from "@/lib/url";

function memberScopeCallbackUrl(
	ownerSlug: string,
	entityScope?: string,
): string {
	if (entityScope) {
		const [entityType, slug, ...rest] = entityScope.split("/");
		if (entityType && slug) {
			const segments: EntityPathSegment[] = [
				{
					entity_type: entityType,
					slug: rest.length > 0 ? [slug, ...rest].join("/") : slug,
				},
			];
			return buildMemoryEntityScopePath(ownerSlug, segments);
		}
	}
	const params = new URLSearchParams({ type: "$member" });
	return `/${ownerSlug}/memory?${params.toString()}`;
}

function MemberGatePrompt({
	title,
	body,
	ctaLabel,
	showCta,
	callbackUrl,
}: {
	title: string;
	body: string;
	ctaLabel?: string;
	showCta?: boolean;
	callbackUrl: string;
}) {
	return (
		<TabEmptyState icon={Users} title={title} description={body}>
			{ctaLabel && showCta ? (
				<Button asChild className="mt-4">
					<Link
						to="/auth/login"
						search={signInSearch({ callbackUrl, intent: "sign-in" })}
					>
						{ctaLabel}
					</Link>
				</Button>
			) : null}
		</TabEmptyState>
	);
}

/**
 * Membership gate for the `$member` memory scope. Page chrome (Memory header +
 * tabs) stays visible; only the body region swaps while auth/membership
 * resolves or when the viewer must sign in / join.
 */
export function MemberScopeGate({
	ownerSlug,
	entityScope,
	children,
}: {
	ownerSlug: string;
	entityScope?: string;
	children: ReactNode;
}) {
	const { isAuthenticated, isReady } = useAuthState();
	const { isMember, isLoading: isOrgLoading } = useCurrentOrg();
	const callbackUrl = memberScopeCallbackUrl(ownerSlug, entityScope);

	if (!isReady || isOrgLoading) {
		return <MembersBodySkeleton />;
	}

	if (!isAuthenticated) {
		return (
			<MemberGatePrompt
				title="Sign in to see members"
				body="The members of this workspace are only visible to people who have signed in."
				ctaLabel="Sign in"
				showCta
				callbackUrl={callbackUrl}
			/>
		);
	}

	if (!isMember) {
		return (
			<MemberGatePrompt
				title="Join to see members"
				body="Emails and member details are only visible to members of this workspace. Use the banner above to join."
				callbackUrl={callbackUrl}
			/>
		);
	}

	return <>{children}</>;
}
import { useQuery } from '@tanstack/react-query';
import { organization } from '@/lib/auth';
import { useAuthState } from '@/lib/auth-state';

type Role = 'member' | 'admin' | 'owner';

export interface Member {
  id: string;
  userId: string;
  organizationId: string;
  role: Role;
  createdAt: Date;
  user: {
    id: string;
    name: string;
    email: string;
    image?: string;
  };
}

interface UseMembersResult {
  members: Member[];
  isLoading: boolean;
  currentUserRole: Role | null;
  isAdmin: boolean;
}

export function useMembers(organizationId: string | undefined): UseMembersResult {
  const { session } = useAuthState();

  const { data: members = [], isLoading } = useQuery({
    queryKey: ['org-members', organizationId],
    queryFn: async () => {
      if (!organizationId) return [];
      const res = await organization.listMembers({ query: { organizationId } });
      return (res.data?.members as Member[]) ?? [];
    },
    enabled: !!organizationId,
    staleTime: 60_000,
  });

  const currentUserId = session?.user?.id;
  const currentMember = currentUserId ? members.find((m) => m.userId === currentUserId) : undefined;
  const currentUserRole = (currentMember?.role as Role) ?? null;

  return {
    members,
    isLoading,
    currentUserRole,
    isAdmin: currentUserRole === 'admin' || currentUserRole === 'owner',
  };
}
