/**
 * Reverse-lookup: given the connector groups and a set of selected connection
 * ids, return the `connector_key` that owns all of them (the connector to expand
 * in the cascade dropdown / to build a "Manage" link for). Returns undefined
 * when any id is unmatched or belongs to another connector. Structurally typed
 * so this lib stays free of the connections-API import.
 */
export function connectorForConnectionIds(
	groups: ReadonlyArray<{
		connector_key: string;
		connections: ReadonlyArray<{ id: number }>;
	}>,
	connectionIds: ReadonlySet<string>,
): string | undefined {
	if (connectionIds.size === 0) return undefined;
	let match: string | undefined;
	const matchedIds = new Set<string>();
	for (const group of groups) {
		for (const connection of group.connections) {
			const id = String(connection.id);
			if (connectionIds.has(id)) {
				if (match && match !== group.connector_key) return undefined;
				match = group.connector_key;
				matchedIds.add(id);
			}
		}
	}
	return matchedIds.size === connectionIds.size ? match : undefined;
}

