import { Link } from "@tanstack/react-router";
import { ChevronRight } from "lucide-react";
import { buildEntityUrl } from "@/lib/url";
import type { EntityReference } from "./types";

interface EntityLinkCellProps {
	ownerSlug: string;
	entity: EntityReference;
	/** Which consolidated surface this entity drills into. */
	tab: "events" | "watchers";
	className?: string;
}

function buildEntityOverviewUrl(
	ownerSlug: string,
	entity: EntityReference,
): string {
	const segments =
		entity.parentEntityType && entity.parentEntitySlug
			? [
					{
						entity_type: entity.parentEntityType,
						slug: entity.parentEntitySlug,
					},
					{ entity_type: entity.entityType, slug: entity.entitySlug },
				]
			: [{ entity_type: entity.entityType, slug: entity.entitySlug }];
	return buildEntityUrl(ownerSlug, segments);
}

/**
 * Entity name with a drill-down link. Used in org-wide tables (memory / watchers)
 * to filter the consolidated page to a single entity. Falls back to the entity's
 * overview page when we don't have a numeric id to filter by.
 */
export function EntityLinkCell({
	ownerSlug,
	entity,
	tab,
	className,
}: EntityLinkCellProps) {
	const url =
		entity.entityId != null && tab === "events"
			? `/${ownerSlug}/memory?entity_id=${entity.entityId}`
			: buildEntityOverviewUrl(ownerSlug, entity);

	return (
		<Link
			to={url as "/"}
			className={`flex items-center gap-1 text-primary hover:underline group ${className ?? ""}`}
		>
			<span className="font-medium">{entity.entityName}</span>
			<ChevronRight className="h-3 w-3 opacity-0 group-hover:opacity-100 transition-opacity" />
		</Link>
	);
}
