// Uses fetchWithTimeout directly (REST endpoint, not tool-based).
// Drives the social-providers picker on auth/login. Don't mount globally —
// every page paying for an XHR that only login.tsx consumes is wasteful.
export function useAuthConfig(options?: { enabled?: boolean }) {
	return useQuery({
		queryKey: [
			"auth-config",
			typeof window !== "undefined" ? window.location.pathname : null,
		],
		enabled: options?.enabled ?? true,
		queryFn: async () => {
			const url = new URL(`${API_URL}/api/auth-config`);
			if (typeof window !== "undefined") {
				url.searchParams.set("callbackUrl", window.location.href);
			}
			const response = await fetchWithTimeout(url.toString());
			if (!response.ok) {
				throw await apiErrorFor(response);
			}
			return (await response.json()) as AuthConfig;
		},
		staleTime: 5 * 60 * 1000,
	});
}

