export type OrganizationVisibility = Organization["visibility"];

export async function updateOrganizationVisibility(
	orgContext: string | ApiOrgContext,
	visibility: OrganizationVisibility,
): Promise<Organization> {
	const scope = resolveApiScope(orgContext);
	const response = await fetchWithTimeout(
		`${API_URL}/api/${scope.slug}/organization/visibility`,
		{
			method: "PATCH",
			headers: { "Content-Type": "application/json" },
			credentials: "include",
			body: JSON.stringify({ visibility }),
		},
	);

	if (!response.ok) {
		throw await apiErrorFor(response);
	}

	const result = (await response.json()) as { organization?: Organization };
	if (!result.organization) {
		throw new Error(
			"Organization visibility update did not return an organization.",
		);
	}
	return result.organization;
}

// Uses fetchWithTimeout directly (REST endpoint, not tool-based)
export function useOrganizations(options?: { search?: string }) {
	return useQuery({
		queryKey: ["organizations", options?.search],
		queryFn: async () => {
			const params = new URLSearchParams();
			if (options?.search) params.append("search", options.search);

			const url = `${API_URL}/api/organizations${params.toString() ? `?${params}` : ""}`;
			const response = await fetchWithTimeout(url, { credentials: "include" });
			if (!response.ok) {
				throw await apiErrorFor(response);
			}
			const result = await response.json();
			return (result.organizations || []) as Organization[];
		},
		staleTime: 300000,
	});
}

