						{
							id: "claude-old",
							kind: "mcp",
							title: "Claude Desktop",
							registrationGroupKey: "claude:user-a:private-org",
							status: "disconnected",
							authState: "revoked",
							lastSeenAt: 100,
						},
					],
				}),
			),
			http.post("*/api/private-org/read_knowledge", async ({ request }) => {
				const body = (await request.json()) as { client_ids?: unknown };
				capturedClientIds = body.client_ids;
				return HttpResponse.json({
					content: [],
					total: 0,
					classification_stats: {},
					page: { limit: 50, offset: 0, has_more: false },
